window.FC_DESTELER=[{"id":"d01","no":"1","ad":"Kapsam, Bakım ve Etik","renk":"#60A5FA","konu":"konu-01-kapsam","kartlar":[{"id":"ca740bf8f5","f":"<b>Software crisis</b> nedir? Üç belirtisi?","b":"Yazılımın:<br><ol style='text-align:left'><li><b>geç</b> teslim edilmesi (late)</li><li><b>bütçeyi aşması</b> (over budget)</li><li>içinde <b>kalıntı hatalar</b> olması (with residual faults)</li></ol><div style='text-align:left'><i>EN:</i> <i>Software is delivered late, over budget and with residual faults.</i></div>","t":["tanim","cikmis"]},{"id":"036067d5c0","f":"&quot;Software engineering&quot; terimi nerede ve hangi amaçla ortaya atıldı?","b":"<b>1968 NATO Konferansı</b>, Garmisch (Almanya). Amaç: <b>software crisis</b>'i çözmek.","t":["tanim"]},{"id":"f20a2804dd","f":"Standish Group 2006 verisine göre projelerin yüzde kaçı başarılı, kaçı &quot;challenged&quot;, kaçı iptal?","b":"%35 başarılı, %46 challenged (geç / bütçe üstü / eksik özellik), %19 iptal ya da hiç kullanılmadı.<br>Yani &quot;üç projeden ancak biri başarılı&quot;. Kriz çözülmedi: <b>software depression</b>.","t":["sayi"]},{"id":"825941eb21","f":"Yeni kodlama yöntemi CM<sub>new</sub>, eskisinden %10 hızlı. Yazılım mühendisi &quot;hemen geçelim&quot; der mi? Neye bakar?","b":"Hayır, önce şunlar düşünülür:<br><ol style='text-align:left'><li>Personelin <b>eğitim maliyeti</b></li><li>Yeni teknolojiye geçişin <b>etkisi</b> (yeni araç, ek personel, düzenin bozulması)</li><li>Yöntemin <b>bakıma etkisi</b></li></ol>Kodlama + birim testi toplam maliyetin sadece ≈ %8,5'i → kazanç en fazla %0,85. <b>Asıl kazanç bakımdadır.</b>","t":["kavram"]},{"id":"4bf3912cca","f":"Bakım maliyetini %10 düşüren bir teknik toplam maliyeti ne kadar düşürür? Kodlamayı %10 hızlandıran?","b":"Bakım ≈ %75 → 0,10 × 75 = <b>%7,5</b> düşüş.<br>Kodlama+birim test ≈ %8,5 → en fazla <b>%0,85</b>.<br>Sonuç: yatırım bakımı kolaylaştıran tekniklere yapılmalı.","t":["sayi"]},{"id":"d6c54c84f9","f":"<b>Life-cycle model</b> ile <b>life cycle</b> farkı?","b":"<b>Life-cycle model:</b> yazılım geliştirirken izlenecek adımların teorik tarifi (&quot;ne yapılmalı&quot;).<br><b>Life cycle:</b> belirli bir ürün için <i>gerçekte</i> uygulanan adımlar.","t":["tanim","karsilastirma"]},{"id":"5ff7c75498","f":"Klasik (waterfall) modelin fazlarını sırayla yaz.","b":"<ol style='text-align:left'><li>Requirements</li><li>Analysis (specification)</li><li>Design</li><li>Implementation</li><li>Postdelivery maintenance</li><li>Retirement</li></ol><div style='color:#888;font-size:0.85em'>💡 Planning, testing ve documentation AYRI faz değildir.</div>","t":["liste","cikmis"]},{"id":"952b04e5a5","f":"Klasik modelde <b>analysis (specification)</b> fazında ne yapılır? Hangi soruyu cevaplar?","b":"Gereksinimler analiz edilir, <b>specification document</b> ve <b>SPMP</b> hazırlanır.<br>Soru: Ürün <b>ne</b> yapacak?","t":["kavram"]},{"id":"fd36884a5d","f":"Klasik modelde <b>design</b> fazının iki adımı? Hangi soruyu cevaplar?","b":"<ol style='text-align:left'><li><b>Architectural design:</b> ürünü modüllere ayırma</li><li><b>Detailed design:</b> her modülün veri yapıları ve algoritmaları</li></ol>Soru: Ürün bunu <b>nasıl</b> yapacak?","t":["kavram"]},{"id":"239d5edfcc","f":"Üç bakım türü nedir? (çıkmış test sorusu)","b":"<ol style='text-align:left'><li><b>Corrective</b> (düzeltici)</li><li><b>Perfective</b> (mükemmelleştirici)</li><li><b>Adaptive</b> (uyarlayıcı)</li></ol>&quot;Reliable&quot; bir bakım türü <b>değildir</b>.","t":["liste","cikmis","test"]},{"id":"5edb5d5b6b","f":"<b>Corrective maintenance</b> nedir? Örnek?","b":"Kalıntı hataların (residual faults) giderilmesi; spesifikasyon değişmez (<i>software repair</i>).<br>Örnek: faiz yanlış hesaplanıyor, düzeltilir.","t":["tanim"]},{"id":"30de1226a4","f":"<b>Perfective maintenance</b> nedir? Örnek?","b":"Müşterinin ürünün etkinliğini artıracağını düşündüğü değişiklikler: yeni işlev, daha kısa yanıt süresi.<br>Örnek: rapora yeni sütun eklemek, sistemi hızlandırmak.","t":["tanim"]},{"id":"2c5117fb5c","f":"<b>Adaptive maintenance</b> nedir? Örnek?","b":"Ürünün çalıştığı <b>ortam</b> değişince yapılan değişiklikler: yeni donanım/işletim sistemi, yeni yasal düzenleme.<br>Örnek: KDV oranı değişti; Teal Tractors'ta Kanada vergisi ve CAD para birimi.","t":["tanim"]},{"id":"dd2aec2b2d","f":"Hangi iki bakım türüne birlikte <b>enhancement</b> (software update) denir?","b":"<b>Perfective + adaptive</b>.","t":["tanim"]},{"id":"164657ccc3","f":"Senaryo: Yeni çıkan vergi yasası yüzünden faturalama modülü değiştiriliyor. Bakım türü?","b":"<b>Adaptive</b> — ürünün ortamı (yasal düzenleme) değişti.","t":["senaryo"]},{"id":"32a75dddab","f":"Senaryo: Müşteri, rapor ekranına &quot;PDF olarak indir&quot; düğmesi istiyor. Bakım türü?","b":"<b>Perfective</b> — yeni işlev / ürünün etkinliğini artırma.","t":["senaryo"]},{"id":"ac4b97b9a4","f":"Senaryo: Kullanıcı, toplam tutarın yanlış hesaplandığını bildiriyor ve hata düzeltiliyor. Bakım türü?","b":"<b>Corrective</b> — kalıntı hata gideriliyor, spesifikasyon değişmiyor.","t":["senaryo"]},{"id":"60175ee621","f":"Bakımın <b>klasik</b> tanımı nedir? Neden &quot;temporal&quot; denir?","b":"<b>Development-then-maintenance</b> modeli: ürün kurulduktan sonra yapılan her değişiklik bakımdır.<br>Temporal: bir etkinliğin bakım mı geliştirme mi olduğu <i>ne zaman yapıldığına</i> bağlıdır.","t":["tanim","karsilastirma"]},{"id":"9491004f17","f":"Klasik bakım tanımının iki saçma sonucu nedir?","b":"<ol style='text-align:left'><li>Aynı hata kurulumdan <b>1 gün sonra</b> düzeltilirse bakım, <b>1 gün önce</b> düzeltilirse geliştirme sayılır.</li><li>Müşteri işlevi kurulumdan sonra isterse perfective bakım, hemen önce isterse (moving target) geliştirme sayılır.</li></ol>Ayrıca günümüzde sıfırdan geliştirme nadir, <b>reuse</b> yaygın.","t":["kavram"]},{"id":"e01ffa8d06","f":"<b>Modern maintenance</b> nedir? (çıkmış test sorusu)","b":"ISO/IEC 12207 (1995): bakım, yazılım bir problem nedeniyle ya da iyileştirme/uyarlama ihtiyacıyla değiştirildiğinde gerçekleşir.<br><b>Maintenance occurs whenever software is modified</b> — kurulumdan önce ya da sonra fark etmez. <b>Operational</b> tanımdır.<div style='text-align:left'><i>EN:</i> <i>Modern maintenance is an operational definition: maintenance occurs whenever software is modified because of a problem or a need for improvement or adaptation, regardless of whether it takes place before or after installation.</i></div>","t":["tanim","cikmis","test"]},{"id":"93bf53ef7b","f":"<b>Postdelivery maintenance</b> nedir?","b":"Ürün teslim edilip kurulduktan <b>sonra</b> yapılan değişiklikler (IEEE 1990).","t":["tanim"]},{"id":"9c7cc1ccc5","f":"Toplam yazılım maliyetinin ne kadarı postdelivery maintenance'a gider?","b":"1976–81: ≈ <b>%67</b>; 1992–98: ≈ <b>%75</b> (birçok kurumda %70–80).","t":["sayi"]},{"id":"1425c9c1b3","f":"İyi yazılım ile kötü yazılımın kaderi farkı? (bakımın önemi)","b":"Kötü yazılım atılır; <b>iyi yazılım 10–20 yıl bakımla yaşar</b>. Yazılım sürekli değişen gerçek dünyanın modelidir.","t":["kavram"]},{"id":"cba050777c","f":"Hatayı erken bulmak neden önemli? Gereksinim hatası bakımda kaç kat pahalı?","b":"Ne kadar erken bulunursa o kadar ucuz: gereksinim hatasını bakımda düzeltmek ≈ <b>100–200 kat</b> pahalı (Boehm).<br>Erken: sadece bir <b>doküman</b> değişir. Geç: kod + doküman değişir, değişiklik test edilir, <b>regression testing</b>, yeniden kurulum.","t":["kavram"]},{"id":"60a6ffa37d","f":"Büyük projelerde hataların yüzde kaçı requirements/analysis/design kaynaklı?","b":"<b>%60–70</b>. JPL: spesifikasyonda sayfa başına 1,9; tasarımda 0,9; kodda 0,3 hata.","t":["sayi"]},{"id":"74fa6aff93","f":"Takım çalışmasının iki temel sorunu?","b":"<ol style='text-align:left'><li>Modüller arası <b>arayüz (interfacing)</b> problemleri</li><li>Takım üyeleri arası <b>iletişim</b> problemleri</li></ol>","t":["liste"]},{"id":"bc13703256","f":"Hangi üç etkinlik <b>ayrı bir faz değildir</b>?","b":"<ol style='text-align:left'><li><b>Planning</b></li><li><b>Testing</b></li><li><b>Documentation</b></li></ol>Üçü de bütün yaşam döngüsü boyunca sürer.","t":["liste","cikmis"]},{"id":"cc83ed1a94","f":"Which one is NOT a separate phase during software development?<br>a) Implementation b) Analysis c) Design d) Documentation e) Requirement","b":"<b>d) Documentation</b> — diğer bütün etkinliklerle paralel yürütülür.","t":["cikmis","test"]},{"id":"b27d4bac3d","f":"Neden ayrı bir <b>planning</b> fazı yok?","b":"Projenin başında neyin yapılacağını tam bilmediğimiz için baştan tam plan yapılamaz. Başta ön plan yapılır; SPMP ancak spesifikasyon onaylandıktan (signed off) sonra hazırlanır. <b>Planlama bütün yaşam döngüsü boyunca yapılır.</b>","t":["kavram"]},{"id":"cd517326fa","f":"Neden ayrı bir <b>testing</b> fazı yok?","b":"Geliştirme bitince test etmek çok geçtir. Verification (her faz sonu) geç, validation (proje sonu) çok geç. Test sürekli yapılmalı; sorumlusu her yazılımcı ve <b>SQA</b> grubudur.","t":["kavram"]},{"id":"666777c0f2","f":"Neden ayrı bir <b>documentation</b> fazı yok?","b":"Sonradan yazmak çok geç: kilit kişiler ayrılabilir; önceki fazın belgesi olmadan sonraki faz yapılamaz; belge olmadan test ve bakım yapılamaz. Dokümantasyon <b>bütün etkinliklerle paralel</b> yürür, hep güncel olmalıdır.","t":["kavram"]},{"id":"5c705c6b21","f":"<b>Verification</b> ile <b>validation</b> farkı?","b":"<b>Verification:</b> her fazın sonunda yapılan test — &quot;ürünü doğru mu yapıyoruz?&quot;<br><b>Validation:</b> projenin sonunda ürünün spesifikasyonu karşılayıp karşılamadığının testi — &quot;doğru ürünü mü yaptık?&quot;","t":["tanim","karsilastirma","cikmis"]},{"id":"6255cd2aff","f":"Yapısal (classical) paradigma neden yetersiz kaldı?","b":"<b>50.000 satırdan büyük</b> ürünlerde başarısız oldu, bakım eforun %70–80'ine çıktı. Yöntemler ya <b>action oriented</b> (DFD, sonlu durum makinesi) ya <b>data oriented</b> (ER, Jackson) idi; <b>ikisi birden değil</b>.","t":["kavram"]},{"id":"56c1e97596","f":"<b>Object</b> (nesne) nedir? Banka hesabı örneği?","b":"Hem <b>veriyi</b> hem o veri üzerinde yapılan <b>eylemleri</b> içeren yazılım bileşeni.<br>Banka hesabı: veri <i>accountBalance</i>; eylemler <i>deposit, withdraw, determineBalance</i>. Bakiye gizli, sadece bu metotlarla erişilir.<div style='text-align:left'><i>EN:</i> <i>An object is a software component that incorporates both data and the actions performed on that data.</i></div>","t":["tanim"]},{"id":"630f2d3953","f":"Nesne yönelimli paradigmanın 5 güçlü yanı?","b":"<ol style='text-align:left'><li><b>Information hiding</b> → bakım güvenli, regression fault azalır</li><li>Geliştirme kolay: nesnelerin fiziksel karşılıkları var</li><li>İyi tasarlanmış nesneler <b>bağımsız birimler</b> (encapsulation, mesajlaşma, responsibility-driven design)</li><li><b>Karmaşıklığı azaltır</b> (bağımsız birimler)</li><li><b>Reuse</b>'u destekler</li></ol>","t":["liste"]},{"id":"7ee79b2a57","f":"<b>Responsibility-driven design</b> (design by contract) nedir? Hocanın örneği?","b":"Bir nesneye, işi <b>nasıl</b> yaptığını bilmeden mesaj göndermek; işi yapmak nesnenin <b>sorumluluğudur</b>.<br>Örnek: başka şehirdeki annene çiçek göndermek için çiçek sitesini ararsın; hangi çiçekçinin teslim edeceğini bilmen gerekmez.","t":["tanim"]},{"id":"5904375936","f":"Analiz/tasarım &quot;tümseği&quot; (hump / jolt) nedir? OO paradigma bunu nasıl çözer?","b":"Yapısal paradigmada analiz (ne) → tasarım (nasıl) geçişinde sert bir sıçrama vardır; modüller ancak mimari tasarımda çıkar.<br>OO'da nesneler <b>analiz</b> iş akışında çıkar, tasarımda tasarlanır, kodlamada kodlanır → geçişler yumuşar.","t":["kavram"]},{"id":"30a42174f4","f":"<b>Encapsulation</b> ile <b>information hiding</b> farkı?","b":"<b>Encapsulation:</b> gerçek dünyadaki bir varlıkla ilgili her şeyin (veri + eylem) tek birimde toplanması.<br><b>Information hiding:</b> gerçekleştirme ayrıntılarının gizlenmesi; diğer modüller onlara bağımlı olamaz, değişiklik yerel kalır.","t":["tanim","karsilastirma"]},{"id":"22a1e0b678","f":"<b>Mistake → fault → failure → error</b> zincirini açıkla.","b":"<ol style='text-align:left'><li><b>Mistake:</b> programcının yaptığı yanlışlık</li><li><b>Fault:</b> bunun koda giren sonucu (hata)</li><li><b>Failure:</b> hatanın yol açtığı, gözlenen yanlış davranış</li><li><b>Error:</b> sonucun <i>ne kadar yanlış olduğunun ölçüsü</i> (IEEE 610.12, nicel tanım)</li></ol><b>Defect:</b> fault/failure/error için genel terim. &quot;Bug&quot; sorumluluğu atar.","t":["tanim","liste"]},{"id":"978ed209e4","f":"<b>Internal</b> ile <b>contract software</b> farkı?","b":"<b>Internal:</b> müşteri ve geliştirici aynı kurumda.<br><b>Contract:</b> müşteri ve geliştirici farklı kurumlarda.","t":["tanim","karsilastirma"]},{"id":"b2c85d523c","f":"<b>COTS</b> ne demek?","b":"<b>Commercial off-the-shelf</b>: raftan satılan hazır paket ticari yazılım.","t":["tanim"]},{"id":"15dba31bb9","f":"Open-source yazılımla ilgili <b>Linus's Law</b> nedir?","b":"&quot;Yeterince göz varsa bütün hatalar sığdır.&quot; (Given enough eyeballs, all bugs are shallow.)","t":["tanim"]},{"id":"916f46e1c8","f":"<b>Program / system / product</b> farkı?","b":"Program: kod parçası. System: birlikte çalışan programlar. Product: bunların tamamı + belgeleri.","t":["tanim"]},{"id":"fb42d357e5","f":"Software Engineering Code of Ethics'i kim yayımladı? Kaç ilke?","b":"<b>ACM ve IEEE-CS</b> ortak (sürüm 5.2, 1999). Preamble + <b>8 ilke</b>.<div style='color:#888;font-size:0.85em'>💡 Hoca: &quot;I ask this code of ethics in the exam&quot;.</div>","t":["hoca_sorar"]},{"id":"374d619f38","f":"Code of Ethics'in <b>8 ilkesini</b> sırayla yaz.","b":"<ol style='text-align:left'><li>Public</li><li>Client and Employer</li><li>Product</li><li>Judgment</li><li>Management</li><li>Profession</li><li>Colleagues</li><li>Self</li></ol><div style='color:#888;font-size:0.85em'>💡 Dışarıdan içeriye: toplum → müşteri → ürün → yargın → yönetim → meslek → meslektaş → kendin.</div>","t":["liste","hoca_sorar","ezber"]},{"id":"d72fab4b4d","f":"Etik ilke 1: <b>Public</b>","b":"Software engineers shall act consistently with the <b>public interest</b>.<br>(Kamu yararına uygun davran.)","t":["etik"]},{"id":"080df1bc18","f":"Etik ilke 2: <b>Client and Employer</b>","b":"…act in a manner that is in the best interests of their <b>client and employer</b>, consistent with the public interest.<br>(Kamu yararıyla çelişmeden müşteri ve işverenin çıkarını gözet.)","t":["etik"]},{"id":"2deb7c37f8","f":"Etik ilke 3: <b>Product</b>","b":"…ensure that their products and related modifications meet the <b>highest professional standards</b> possible.","t":["etik"]},{"id":"53da2ca771","f":"Etik ilke 4: <b>Judgment</b>","b":"…maintain <b>integrity and independence</b> in their professional judgment.<br>(Mesleki yargıda dürüstlük ve bağımsızlık.)","t":["etik"]},{"id":"6ccba31cf7","f":"Etik ilke 5: <b>Management</b>","b":"Software engineering <b>managers and leaders</b> shall subscribe to and promote an ethical approach to the management of software development and maintenance.","t":["etik"]},{"id":"aeeb599b10","f":"Etik ilke 6: <b>Profession</b>","b":"…advance the <b>integrity and reputation of the profession</b> consistent with the public interest.","t":["etik"]},{"id":"9cea5a2881","f":"Etik ilke 7: <b>Colleagues</b>","b":"…be <b>fair to and supportive of</b> their colleagues.","t":["etik"]},{"id":"6529abc16d","f":"Etik ilke 8: <b>Self</b>","b":"…participate in <b>lifelong learning</b> regarding the practice of their profession and promote an ethical approach.","t":["etik"]},{"id":"13173ee397","f":"Hangi etik ilke &quot;lifelong learning&quot;i söyler? Hangisi &quot;integrity and independence&quot;ı?","b":"Lifelong learning → <b>8. Self</b>.<br>Integrity and independence in judgment → <b>4. Judgment</b>.","t":["etik"]},{"id":"4a0b788ebd","f":"Yazılım geliştiren/bakan kişilerin taşıması gereken özellikler (kitap)?","b":"Hard working, intelligent, sensible, up to date ve her şeyden önce <b>ethical</b>.","t":["liste"]}]},{"id":"d02","no":"2","ad":"Yaşam Döngüsü ve Stable Intermediate Forms","renk":"#C084FC","konu":"konu-02-yasam-dongusu","kartlar":[{"id":"626ce6ea15","f":"<b>Stable Intermediate Forms</b> — ana fikir nedir?","b":"Karmaşık bir sistem her adımda <b>kararlı (çalışan, tutarlı) ara formlardan</b> geçerek gelişirse çok daha hızlı ve güvenli gelişir. Bir değişiklik ters giderse baştan başlanmaz, <b>son kararlı forma geri dönülür</b>. Moving target problemi ve kaçınılmaz hataların etkisini azaltır.<div style='text-align:left'><i>EN:</i> <i>Complex systems evolve much faster and more safely if they pass through stable intermediate forms. If a change fails we return to the last stable form instead of starting again.</i></div>","t":["cikmis","hoca_sorar","sif"]},{"id":"713737b7f0","f":"Stable Intermediate Forms'un <b>üç yöntemi</b> nedir?","b":"<ol style='text-align:left'><li><b>Three points of contact</b></li><li><b>Copy before release</b></li><li><b>Iterative and incremental software development</b> (stepwise refinement, snowball effect)</li></ol><div style='color:#888;font-size:0.85em'>💡 2024–25 ve 2025–26 vizelerinin ikisinde de çıktı (15 p). Hoca AÇIKLAMALARINI istiyor; &quot;terms&quot; değil &quot;forms&quot;.</div>","t":["liste","cikmis","hoca_sorar","sif","ezber"]},{"id":"f1d19aaaf2","f":"SIF 1: <b>Three points of contact</b> — açıkla.","b":"Kaya tırmanıcısı benzetmesi: dört uzvundan <b>üçü sabit</b>, yalnızca <b>biri</b> hareket eder; tutamak kayarsa sabit üç noktaya döner.<br>Yazılımda: <b>aynı anda yalnızca tek bir şey değiştirilir</b>, diğer her şey sabit tutulur. Değişiklik test edilip kararlı olunca sıradakine geçilir. Olumsuz sonuçta geri dönmek kolay, hatanın kaynağı belli.<div style='text-align:left'><i>EN:</i> <i>Like a climber who keeps three limbs fixed and moves only one, we change only one thing at a time and keep everything else stable. If the change fails, we can easily go back to the last stable form and we know which change caused the problem.</i></div>","t":["cikmis","hoca_sorar","sif"]},{"id":"9ee140732b","f":"SIF 2: <b>Copy before release</b> — açıkla.","b":"Yeni sürüm yayımlanmadan / değişiklik canlıya alınmadan önce <b>mevcut kararlı sürümün kopyası (yedeği)</b> alınır. Yeni sürümde sorun çıkarsa kararlı kopyaya dönülür (rollback). Sürüm kontrolü ve <b>baseline</b> bunun uygulamasıdır.<div style='text-align:left'><i>EN:</i> <i>Before releasing a new version, a copy (backup) of the current stable version is taken. If the new release causes problems, we can roll back to the stable copy. Each copy is a stable intermediate form (baseline).</i></div>","t":["cikmis","hoca_sorar","sif"]},{"id":"dc8eee466a","f":"SIF 3: <b>Iterative and incremental software development</b> — açıkla.","b":"Ürün artırımlara (mini projeler) bölünür; her artırımda iş akışları hedefe ulaşana kadar yinelenir. Her artırımın sonunda <b>çalışan ama eksik</b> bir ürün = kararlı ara form. Önce en önemli çekirdek (<b>stepwise refinement</b>, Miller), sonra ürün kartopu gibi büyür (<b>snowball effect</b>).<div style='text-align:left'><i>EN:</i> <i>The product is divided into increments. In each increment the workflows are iterated, so at the end of every increment we have a working but incomplete product, i.e. a stable intermediate form. We start with the most important core (stepwise refinement) and grow the product like a snowball.</i></div>","t":["cikmis","hoca_sorar","sif"]},{"id":"3656fbad70","f":"Hoca &quot;Stable Intermediate Forms&quot;u hangi slayt açıkken ve hangi problemle ilişkilendirerek anlattı?","b":"<b>Moving Target Problem</b> slaytı (Slide 2.43). SIF, moving target ve kaçınılmaz hataların etkisini azaltmanın yoludur.","t":["sif"]},{"id":"be401889a0","f":"Snowball effect (kartopu etkisi) nedir?","b":"Önce çekirdek (en öncelikli) kısım yapılır, sonra her artırımda yeni özellikler eklenerek ürün kartopu gibi büyür.","t":["tanim","sif"]},{"id":"780166eef2","f":"Gerçek dünyada yazılım neden doğrusal (linear) ve sıfırdan geliştirilemez? İki sebep.","b":"<ol style='text-align:left'><li>İnsanlar <b>hata yapar</b> (we make mistakes)</li><li>Geliştirme sırasında <b>müşterinin gereksinimleri değişir</b> (moving target)</li></ol>","t":["kavram"]},{"id":"ae1a6f775f","f":"Winburg mini vaka çalışması: sistem ve iki gereksinim nedir?","b":"Belediye otobüslerinde yalnızca 1$ banknot kabul eden <b>ücret makinesi</b>; görüntü tanıma algoritmasıyla banknotun geçerliliğine karar verir.<br>Gereksinimler: ortalama yanıt süresi <b>&lt; 1 saniye</b>, doğruluk <b>≥ %98</b>.","t":["vaka"]},{"id":"df6f3c5e1c","f":"Winburg Episode 2: ne oldu, hata türü ne?","b":"Yanıt süresi 10 s çıktı; sebep her yerde <i>double precision</i>. Single precision yeterliydi.<br>→ <b>Implementation fault</b> (corrective).","t":["vaka"]},{"id":"5be475dbb5","f":"Winburg Episode 3: ne oldu, hata türü ne?","b":"Düzeltme bitse bile süre 4,5 s olacaktı; sorun karmaşık algoritma. Yeni hızlı algoritmayla <b>yeniden tasarlandı</b>.<br>→ <b>Design fault</b> (corrective).","t":["vaka"]},{"id":"36e0127ba4","f":"Winburg Episode 4: ne oldu, değişiklik türü ne?","b":"Belediye başkanı ürünü satmak için doğruluğun artırılmasını istedi → %99,5.<br>→ <b>Gereksinim değişikliği</b> (perfective).","t":["vaka"]},{"id":"e82f7e8288","f":"Winburg Epilogue: ne oldu, bakım türü ne?","b":"Birkaç yıl sonra sensörler/donanım değişti, yazılım yeniden yazıldı → <b>adaptive</b>.","t":["vaka"]},{"id":"b5367f615f","f":"<b>Evolution-tree modeli</b> waterfall'a göre neyi gösterebilir?","b":"Waterfall geri besleme oklarıyla Winburg'u gösterir ama <b>olayların sırasını gösteremez</b>. Evolution-tree her bölümde hangi artifact'ın hangi sürümünün üretildiğini ve <b>sırasını</b> gösterir. İki boyutludur.","t":["kavram"]},{"id":"a8e104b2f9","f":"<b>Baseline</b> nedir? Winburg Episode 3 sonundaki baseline?","b":"Belirli bir andaki artifact'ların <b>tam kümesi</b>.<br>Episode 3 sonu: Requirements₁, Analysis₁, Design₃, Implementation₃.","t":["tanim"]},{"id":"9e0dd3022d","f":"Winburg'un dersi nedir?","b":"<b>Değişiklik her zaman gerekir</b>: yazılım sürekli değişen gerçek dünyanın modelidir ve yazılımcılar insandır, hata yapar.","t":["kavram"]},{"id":"42367f8346","f":"<b>Moving target problem</b> nedir? Çözümü var mı?","b":"Yazılım ürünü geliştirilirken <b>gereksinimlerin değişmesi</b>. Sebep iyi olsa bile modüller arasında bağımlılıklar oluşur, regression fault'lara yol açar; çok değişiklikte ürün yeniden tasarlanır.<br><b>Çözümü yoktur</b>, sadece etkisi azaltılabilir.<div style='text-align:left'><i>EN:</i> <i>A change in the requirements while the software product is being developed. There is no solution; its effects can only be minimized.</i></div>","t":["tanim","cikmis"]},{"id":"b2b5249ea5","f":"Teal Tractors vakasında moving target'a yol açan değişiklik neydi?","b":"Şirket <b>Kanada'ya genişledi</b>: yeni satış bölgeleri, Kanada vergileri ve iş kuralları, iki para birimi (USD ve CAD).","t":["vaka"]},{"id":"24a94d5a6c","f":"<b>Regression fault</b> nedir?","b":"Başka bir yerde yapılan değişiklik yüzünden yazılımın <b>görünüşte ilgisiz</b> bir bölümünde ortaya çıkan hata.<div style='text-align:left'><i>EN:</i> <i>A fault in an apparently unrelated part of the software caused by a change made elsewhere.</i></div>","t":["tanim","cikmis"]},{"id":"ee2d97b111","f":"Değişikliği isteyen kişinin yeterli gücü (clout) varsa moving target için ne yapılabilir?","b":"Hiçbir şey; büyüyen şirketler hep değişir. Ancak etkisi iterative-incremental model ve robust mimariyle azaltılır.","t":["kavram"]},{"id":"5068f302b6","f":"<b>Miller's Law</b> nedir?","b":"İnsan aynı anda yaklaşık <b>yedi parça (chunk)</b> bilgiye odaklanabilir.<div style='text-align:left'><i>EN:</i> <i>At any one time we can concentrate on only about seven chunks of information.</i></div>","t":["tanim","cikmis"]},{"id":"e5fe178e58","f":"<b>Stepwise refinement</b> nedir? (3 adım)","b":"<ol style='text-align:left'><li>O an <b>en önemli</b> konulara odaklan</li><li>Daha az kritik olanları <b>ertele</b></li><li>Sonunda her konu ele alınır, ama <b>önem sırasına göre</b></li></ol>Bu artırımlı (incremental) bir süreçtir.","t":["tanim","liste"]},{"id":"084f0a36ce","f":"<b>Iteration</b> nedir?","b":"Temel süreç yinelemelidir: <b>her ardışık sürüm hedefe bir öncekinden daha yakındır</b>. Bir artırım içinde hedefe ulaşılana kadar aynı iş akışları tekrarlanır.<div style='text-align:left'><i>EN:</i> <i>Each successive version is closer to the target than its predecessor.</i></div>","t":["tanim","cikmis"]},{"id":"e0cb6c313f","f":"<b>Incrementation</b> nedir?","b":"Ürün parçalara (artırımlara) bölünür; her artırımda ürüne <b>yeni işlevler eklenir</b> (adım adım büyütme).","t":["tanim","cikmis"]},{"id":"fbcbf03fe0","f":"Iteration ve incrementation birlikte nasıl kullanılır?","b":"Tek bir &quot;requirements phase&quot; ya da &quot;design phase&quot; yoktur; her iş akışının birden çok örneği vardır. Artırım sayısı 4, yineleme sayısı 3 olmak zorunda değildir.","t":["kavram"]},{"id":"48b35412c0","f":"Beş çekirdek iş akışı (core workflows) nedir?","b":"<ol style='text-align:left'><li>Requirements</li><li>Analysis</li><li>Design</li><li>Implementation</li><li>Test</li></ol>Bütün yaşam döngüsü boyunca yürütülür; başta requirements, sonda implementation ve test baskındır.","t":["liste"]},{"id":"76415e3084","f":"İterative-incremental modelde &quot;her yineleme&quot; neye benzetilir? Yönetimi neden disiplinlidir?","b":"Her yineleme <b>küçük ama tam bir waterfall modelidir</b>; model art arda uygulanan waterfall olduğu için waterfall kadar disiplinlidir.","t":["kavram"]},{"id":"f19fc178dd","f":"Iterative-incremental modelin <b>5 güçlü yanı</b>?","b":"<ol style='text-align:left'><li>Doğruluğu kontrol için <b>birçok fırsat</b>; hatalar erken bulunur</li><li>Mimarinin <b>robustness</b>'ı yaşam döngüsünün başında belirlenir</li><li><b>Riskler erken azaltılır</b> (mitigate)</li><li>Baştan itibaren <b>çalışan bir sürüm</b> vardır; müşteri geri bildirimi erken</li><li><b>Deneysel kanıt</b>: Standish CHAOS raporlarında başarı oranı arttı</li></ol>","t":["liste","cikmis"]},{"id":"b4de8e8fe5","f":"<b>Architecture</b> ve <b>robustness</b> tanımları?","b":"<b>Architecture:</b> bileşen modüller ve birbirine nasıl oturdukları.<br><b>Robustness:</b> dağılmadan genişlemeyi ve değişikliği kaldırabilme özelliği.","t":["tanim"]},{"id":"051e5600c5","f":"Winburg, iterative-incremental modelin üstüne oturtulunca bölümler neye karşılık gelir?","b":"Her bölüm (episode) bir <b>artırıma</b>; her artırım her iş akışını içermek zorunda değil. Episode 2–3 corrective, Episode 4 perfective bakım.","t":["vaka"]},{"id":"0a26a45eba","f":"<b>Code-and-fix</b> modeli nedir?","b":"Tasarım/spesifikasyon olmadan kodla, sonra düzelt. Küçük programlar dışında kötüdür.","t":["model"]},{"id":"9b7c9865cd","f":"<b>Rapid prototyping</b> modeli nedir?","b":"Müşteriye hızlıca bir prototip gösterip gereksinimleri netleştirme; prototip sonra atılır.","t":["model"]},{"id":"1e2436ef80","f":"<b>Spiral</b> modelin odağı nedir?","b":"Her döngüde <b>risk analizi</b>; odak risklerdir.","t":["model"]},{"id":"a4d102b160","f":"<b>Synchronize-and-stabilize</b> modeli kimin modelidir, özelliği?","b":"<b>Microsoft</b> modeli; her gün bileşenler birleştirilip test edilir (daily build).","t":["model"]},{"id":"c292fc8db3","f":"<b>Agile processes</b> özü?","b":"Kısa iterasyonlar, sürekli müşteri teması.","t":["model"]}]},{"id":"d03","no":"3","ad":"Unified Process ve SPMP","renk":"#F472B6","konu":"konu-03-unified-process","kartlar":[{"id":"48ad1eb2dd","f":"<b>What is the Unified Process?</b>","b":"Booch, Jacobson, Rumbaugh'un (1999) <b>nesne yönelimli yazılım geliştirme metodolojisi</b>. Bir dizi adım değildir; ürüne göre değiştirilen <b>uyarlanabilir</b> bir metodolojidir. UML kullanan bir <b>modelleme tekniğidir</b>. <b>Yinelemeli, artırımlı ve iki boyutludur</b>: 5 iş akışı (teknik bağlam) + 4 faz (iş bağlamı).<div style='text-align:left'><i>EN:</i> <i>The Unified Process is an object-oriented software development methodology. It is not a series of steps; it is an adaptable methodology that has to be modified for the specific product. It is a modeling technique (UML), iterative and incremental, and two-dimensional: five core workflows (technical context) and four phases (business context).</i></div>","t":["tanim","cikmis","hoca_sorar"]},{"id":"7183605ca6","f":"Unified Process hangi üç yöntemin birleşimidir?","b":"Booch'un yöntemi, Jacobson'un <b>Objectory</b>'si, Rumbaugh'un <b>OMT</b>'si. Önce RUP, sonra USDP, bugün Unified Process.","t":["tanim"]},{"id":"3674765385","f":"Unified Process neden &quot;herkese uyan tek&quot; bir adımlar dizisi değildir?","b":"Çok farklı türde yazılımlar vardır; tek metodoloji hepsine uymaz. UP <b>adaptable</b>'dır, ürüne göre değiştirilmelidir.","t":["kavram"]},{"id":"df0ce219cc","f":"UP'nin <b>5 çekirdek iş akışı</b>?","b":"<ol style='text-align:left'><li>Requirements</li><li>Analysis</li><li>Design</li><li>Implementation</li><li>Test</li></ol>","t":["liste","cikmis","hoca_sorar","ezber"]},{"id":"29ea5497d2","f":"UP'nin <b>4 fazı</b>? (sırayla)","b":"<ol style='text-align:left'><li>Inception</li><li>Elaboration</li><li>Construction</li><li>Transition</li></ol><div style='color:#888;font-size:0.85em'>💡 Hoca: &quot;Fazlarını ve iş akışlarını sınavda soruyorum.&quot;</div>","t":["liste","cikmis","hoca_sorar","ezber"]},{"id":"a82d8123b5","f":"Which one is NOT a phase of Unified Process?<br>a) Elaboration b) Construction c) Testing d) Transition e) Inception","b":"<b>c) Testing</b> — test bir <b>iş akışıdır (workflow)</b>, faz değildir.","t":["cikmis","test"]},{"id":"e5dc27f713","f":"<b>Workflow</b> ile <b>phase</b> farkı nedir?","b":"<b>Workflow</b> = adımın <b>teknik bağlamı</b> (technical context).<br><b>Phase</b> = adımın <b>iş/ekonomik bağlamı</b> (business context).<br>UP'deki her adım hem bir iş akışına hem bir faza düşer.","t":["tanim","karsilastirma"]},{"id":"13a20cc089","f":"Why do we need a <b>two-dimensional</b> model?","b":"Gerçek projeler tek seferde bitirilemeyecek kadar büyüktür; <b>Miller yasası</b> gereği iş artırımlara (fazlara) bölünür ve her artırımda iş akışları yinelenir. İki boyutlu model hem iş akışlarını hem fazları gösterir; <b>moving target</b> ve kaçınılmaz hatalarla daha iyi başa çıkar.<div style='text-align:left'><i>EN:</i> <i>Real projects are too large to be completed in one pass. Because of Miller's law the task is divided into increments (phases) and within each increment the workflows are iterated. A two-dimensional model handles the moving target problem and inevitable mistakes better.</i></div>","t":["cikmis","kavram"]},{"id":"0a05e9e1b0","f":"Tek boyutlu ve iki boyutlu yaşam döngüsü modellerine örnek?","b":"Tek boyutlu: <b>waterfall</b> (sadece faz ekseni).<br>İki boyutlu: <b>Unified Process</b>, <b>evolution-tree</b>.","t":["karsilastirma"]},{"id":"5a00cb350b","f":"UP moving target problemini ortadan kaldırır mı?","b":"Hayır. Kaçınılmaz değişiklikleri <b>ortadan kaldırmaz, etkilerini azaltır</b>. Bugüne kadarki en iyi çözümdür; gelecekte daha iyisiyle yer değiştirecektir.","t":["kavram"]},{"id":"7fa6da8a5b","f":"<b>Requirements workflow</b>'un amacı ve adımları?","b":"Amaç: müşterinin <b>ihtiyaçlarını</b> (needs) belirlemek, <i>istediklerini</i> (wants) değil.<br><ol style='text-align:left'><li>Uygulama alanını (application domain) anla</li><li>İş modelini (business model) kur</li><li>Müşterinin kısıtlarını (constraints) belirle</li></ol>","t":["workflow"]},{"id":"6ca924b819","f":"Requirements workflow'da belirlenen müşteri <b>kısıtları</b> (constraints)?","b":"<ul style='text-align:left'><li>Deadline (mission critical)</li><li>Parallel running</li><li>Portability</li><li>Reliability</li><li>Rapid response time</li><li>Cost (müşteri bütçeyi nadiren söyler → teklif/ihale)</li></ul>","t":["liste","workflow"]},{"id":"621bb81302","f":"<b>Analysis workflow</b>'un amacı? Neden requirements'tan ayrı?","b":"Gereksinimleri <b>analiz etmek ve inceltmek</b>.<br>Requirements artifact'ları müşterinin anlayacağı <b>doğal dilde</b> olmalı, doğal diller belirsizdir; analysis artifact'ları tasarımcılar için <b>kesin ve tam</b> olmalıdır.","t":["workflow"]},{"id":"11b8dd68d4","f":"Doğal dilin belirsizliğine kitaptaki örnek? (&quot;A harfinin ardından Q&quot;)","b":"&quot;Parça kaydı ve fabrika kaydı okunur. <i>Eğer</i> A'nın hemen ardından Q <i>içeriyorsa</i> taşıma maliyetini hesapla.&quot; — &quot;içeriyorsa&quot;nın öznesi belirsiz: parça kaydı mı, fabrika kaydı mı, veritabanı mı?","t":["workflow"]},{"id":"bcb0b6ba6d","f":"<b>Specification document</b> nedir? Neler içermemelidir?","b":"Müşteri ile geliştirici arasında bir <b>sözleşmedir (contract)</b>. &quot;Optimal&quot;, &quot;%98 tamam&quot; gibi belirsiz ifadeler içermemeli; <b>çelişki (contradictions), eksiklik (omissions), tamamlanmamışlık (incompleteness)</b> olmamalıdır. Test ve bakım için şarttır.","t":["tanim","cikmis"]},{"id":"78c8c20f5d","f":"SPMP (software project management plan) ne zaman hazırlanır? İçeriği (5 öğe)?","b":"Müşteri spesifikasyonu <b>imzaladıktan sonra</b> (mümkün olan en erken zaman).<br><ul style='text-align:left'><li>Cost estimate</li><li>Duration estimate</li><li>Deliverables</li><li>Milestones</li><li>Budget</li></ul>","t":["liste"]},{"id":"337e5a8176","f":"<b>Design workflow</b>'un amacı? Klasik ve OO karşılığı?","b":"Analizi programcıların gerçekleştirebileceği forma gelene kadar inceltmek. Birçok <b>nonfunctional requirement</b> burada kesinleşir (dil, reuse, portability).<br>Klasik: architectural + detailed design. OO: sınıflar analizde çıkarılır, tasarımda tasarlanır.","t":["workflow"]},{"id":"f9c30f271f","f":"Tasarım kararları neden saklanmalı?","b":"Çıkmaz sokağa girilince geri dönebilmek ve bakım ekibinin &quot;tekerleği yeniden icat etmemesi&quot; için.","t":["workflow"]},{"id":"9d42f320f6","f":"<b>Implementation workflow</b>'un amacı?","b":"Hedef ürünü seçilen programlama dilinde gerçekleştirmek; büyük ürün alt sistemlere, onlar da bileşenlere / kod artifact'larına bölünür.","t":["workflow"]},{"id":"8bde94814b","f":"<b>Test workflow</b>: kimin sorumluluğu? Başarılı testin önemli gereksinimi?","b":"Her geliştiricinin, bakımcının ve <b>SQA grubunun</b> sorumluluğu.<br>Gereksinim: <b>traceability</b> — her artifact'taki her öğe bir önceki artifact'taki bir öğeye izlenebilmeli.","t":["workflow"]},{"id":"cfed001d15","f":"<b>Traceability</b> nedir?","b":"Bir artifact'taki her öğenin bir önceki artifact'taki bir öğeye izlenebilmesi (analysis → requirements, design → analysis …).","t":["tanim"]},{"id":"a85517e7fd","f":"Implementation artifact'ları için 4 test türü?","b":"<ol style='text-align:left'><li><b>Unit testing:</b> her bileşen gerçekleştirildiği anda</li><li><b>Integration testing:</b> her yinelemenin sonunda bileşenler birlikte</li><li><b>Product testing:</b> ürün tamamlanmış görününce bütün olarak</li><li><b>Acceptance testing:</b> müşterinin bilgisayarında <b>müşteri</b> tarafından</li></ol>","t":["liste"]},{"id":"7be345e7f7","f":"<b>Alpha release</b> ve <b>beta release</b> nedir?","b":"<b>Alpha:</b> COTS'ta geliştirme testleri sürerken olası müşterilere test için verilen sürüm.<br><b>Beta:</b> neredeyse tamamlanmış, <b>ilk işletme kalitesindeki</b> sürüm (construction fazının çıktısı).<br>Alfa/beta sitesi olmanın avantajı: ürünü erken görmek; dezavantajı: hatalı yazılımla uğraşmak.","t":["tanim","cikmis"]},{"id":"92a75837f1","f":"Requirements/analysis ve design artifact'ları nasıl test edilir? Fark?","b":"<b>Review</b> ile. Requirements/analysis review'unda <b>müşteri temsilcisi</b> bulunur; design review'unda genellikle bulunmaz.","t":["workflow"]},{"id":"6aea658a0e","f":"Postdelivery maintenance'ta iki tür test nedir? Neden önceki testler saklanır?","b":"Yapılan değişikliğin testi + <b>regression testing</b>. Regression testing için önceki bütün test durumları ve beklenen sonuçları saklanmalıdır.","t":["kavram"]},{"id":"29434ce8b3","f":"<b>Gerçek retirement</b> ne zaman olur?","b":"Müşteri kurumun, ürünün sağladığı işleve <b>artık hiç ihtiyacı kalmadığında</b>. (Yeniden yazmak aslında bakımdır; gerçek retirement nadirdir.)","t":["tanim"]},{"id":"8fb2dd876d","f":"<b>Inception phase</b>'in amacı?","b":"Önerilen ürünün <b>ekonomik olarak uygulanabilir (economically viable)</b> olup olmadığını belirlemek. Asıl çıktı: <b>ilk business case</b>.","t":["faz","cikmis"]},{"id":"84492f9302","f":"Inception fazının <b>4 adımı</b>?","b":"<ol style='text-align:left'><li>Understand the domain</li><li>Build the business model</li><li>Delimit the scope of the project</li><li>Begin to make the initial business case</li></ol>","t":["faz","liste","cikmis"]},{"id":"cece5af07a","f":"<b>Business case</b>'te cevaplanan sorular?","b":"<ul style='text-align:left'><li>Ürün maliyet-etkin mi?</li><li>Yatırımın geri dönüşü ne kadar sürer?</li><li>Geliştirmezsek maliyeti ne olur?</li><li>Pazarlanacaksa pazar araştırması yapıldı mı?</li><li>Zamanında teslim edilebilir mi? Geç kalırsa etkisi?</li></ul>","t":["faz"]},{"id":"95acbedfae","f":"<b>Üç ana risk kategorisi</b>?","b":"<ol style='text-align:left'><li><b>Technical risks</b> (ekip deneyimi, donanım zamanında gelir mi, CASE araçları)</li><li><b>The risk of not getting the requirements right</b></li><li><b>The risk of not getting the architecture right</b></li></ol>Riskler sıralanır, kritik olanlar önce azaltılır.","t":["liste","cikmis"]},{"id":"156d618c75","f":"Inception fazında kodlama yapılır mı? Plan ne kadar yapılır?","b":"Genellikle kodlama yok, bazen <b>proof-of-concept prototype</b>. Tüm proje için bilgi yetmediğinden <b>yalnızca elaboration fazının planı</b> yapılır.","t":["faz"]},{"id":"bbe795adc5","f":"Inception fazının çıktıları (deliverables)?","b":"<ul style='text-align:left'><li>Domain model, business model, requirements artifact'larının ilk sürümü</li><li>Analysis artifact'ları ve mimarinin ön sürümü</li><li><b>İlk risk listesi</b></li><li>Use case'lerin ilk sıralaması</li><li>Elaboration fazının planı</li><li><b>Business case'in ilk sürümü</b></li></ul>","t":["faz","liste"]},{"id":"073bfbd237","f":"<b>Elaboration phase</b>'in amacı ve en önemli çıktısı?","b":"İlk gereksinimleri ve mimariyi <b>inceltmek</b>, riskleri izlemek, business case'i inceltmek ve <b>project management plan (SPMP)</b>'ı hazırlamak.<br>Requirements neredeyse tamamlanır, analizin neredeyse tamamı yapılır, mimari tasarıma başlanır.","t":["faz","cikmis"]},{"id":"c6bd1443de","f":"<b>Construction phase</b>'in amacı?","b":"Ürünün <b>ilk işletme kalitesindeki (first operational-quality) sürümünü</b> = <b>beta release</b>'i üretmek. Vurgu implementation ve test'te (unit, integration, product). Çıktı: ilk kullanıcı kılavuzları.","t":["faz","cikmis"]},{"id":"f494ffc145","f":"<b>Transition phase</b>'in amacı?","b":"Müşterinin gereksinimlerinin <b>gerçekten karşılandığından emin olmak</b>: hatalar düzeltilir, kılavuzlar tamamlanır, fark edilmemiş riskler aranır. Beta sitelerinden gelen <b>geri bildirimle</b> yürür.","t":["faz","cikmis"]},{"id":"31d0ad834d","f":"Hangi fazda hangi iş akışı ağırlıklı?","b":"Inception → Requirements<br>Elaboration → Requirements + Analysis<br>Construction → Implementation + Test<br>Transition → Test (geri bildirim)","t":["faz","karsilastirma"]},{"id":"201e4f803c","f":"Hangi fazın sonunda <b>beta release</b> çıkar? Hangi fazda SPMP hazırlanır?","b":"Beta → <b>Construction</b> sonu.<br>SPMP (project management plan) → <b>Elaboration</b>.","t":["faz"]},{"id":"2ab36c4e1d","f":"IEEE SPMP'nin <b>8 ana başlığı</b>? (sırayla)","b":"<ol style='text-align:left'><li>Overview</li><li>Reference materials</li><li>Definitions and acronyms</li><li>Project organization</li><li>Managerial process plans</li><li>Technical process plans</li><li>Supporting process plans</li><li>Additional plans</li></ol><div style='color:#888;font-size:0.85em'>💡 O-R-D-O-M-T-S-A. Hoca: &quot;genelde sınavlarda soruyorum, 1–8 ana başlıkları&quot;.</div>","t":["liste","cikmis","hoca_sorar","ezber","spmp"]},{"id":"31a20fd38b","f":"SPMP 1. <b>Overview</b> neyi içerir?","b":"Project summary (purpose, scope and objectives; assumptions and constraints; deliverables; schedule and budget summary) + evolution of the plan.","t":["spmp"]},{"id":"9f906bda33","f":"SPMP 4. <b>Project organization</b> neyi içerir?","b":"External interfaces, internal structure, roles and responsibilities.","t":["spmp"]},{"id":"27494fa4df","f":"SPMP 5. <b>Managerial process plans</b> neyi içerir?","b":"Start-up plan (estimation, staffing, resource acquisition, training), work plan, control plan, <b>risk management plan</b>, project close-out plan.","t":["spmp"]},{"id":"2a7cb1c922","f":"SPMP 6. <b>Technical process plans</b> neyi içerir?","b":"Process model; methods, tools and techniques; infrastructure plan; product acceptance plan.","t":["spmp"]},{"id":"ec2ef98c2e","f":"SPMP 7. <b>Supporting process plans</b> neyi içerir?","b":"Configuration management, testing, documentation, quality assurance, reviews and audits, problem resolution, subcontractor management, process improvement.","t":["spmp"]},{"id":"0030f3950e","f":"SPMP'de 5. başlık nedir? 7. başlık?","b":"5 → <b>Managerial process plans</b><br>7 → <b>Supporting process plans</b>","t":["spmp","ezber"]},{"id":"f23b9853be","f":"SPMP'de 3. başlık nedir? 6. başlık?","b":"3 → <b>Definitions and acronyms</b><br>6 → <b>Technical process plans</b>","t":["spmp","ezber"]},{"id":"5aa7dedd03","f":"IEEE SPMP çerçevesi neden Unified Process için idealdir?","b":"Her tür ürün için tasarlanmıştır, belirli bir yaşam döngüsü modeli dayatmaz; <b>requirements control</b> ve <b>risk management</b> bölümleri vardır.","t":["spmp"]},{"id":"d8d01f1d66","f":"SEI'ye göre yazılımdaki temel sorun nedir? Hocanın vurgusu?","b":"Sorun <b>sürecin kötü yönetilmesidir</b>. Süreç kaliteliyse ürün de kaliteli olur; belge yoksa ilerleme izlenemez, izlenemezse ölçülemez, ölçülemezse iyileştirilemez.","t":["kavram"]},{"id":"8ea60c0528","f":"<b>CMM</b>'in 5 olgunluk seviyesi?","b":"<ol style='text-align:left'><li><b>Initial</b> (ad hoc, kriz yönetimi)</li><li><b>Repeatable</b> (temel proje yönetimi)</li><li><b>Defined</b> (süreç tamamen belgelenmiş)</li><li><b>Managed</b> (nicel hedefler, ölçüm)</li><li><b>Optimizing</b> (sürekli süreç iyileştirme)</li></ol><div style='color:#888;font-size:0.85em'>💡 Hoca: okuyun ama ISO 25000 daha önemli.</div>","t":["liste"]},{"id":"78a1ce7eb1","f":"ISO 9000 ve ISO/IEC 15504 (SPICE) nedir?","b":"<b>ISO 9000:</b> kalite sistemleri standardı (yazılım için 9000-3).<br><b>ISO/IEC 15504 (SPICE):</b> süreç değerlendirme standardı.","t":["tanim"]}]},{"id":"d04","no":"4","ad":"Cohesion ve Coupling","renk":"#2DD4BF","konu":"konu-04-moduller","kartlar":[{"id":"af4fca023a","f":"<b>Module</b> tanımı nedir? (3 öğe)","b":"<i>A lexically contiguous sequence of program statements, bounded by boundary elements, with an aggregate identifier.</i><br><ul style='text-align:left'><li><b>Lexically contiguous:</b> kodda bitişik satırlar</li><li><b>Boundary elements:</b> { … } / begin … end</li><li><b>Aggregate identifier:</b> modülün tamamına verilen isim</li></ul>","t":["tanim","cikmis"]},{"id":"b9c0f43e06","f":"<code>if (k) { s1; s2; } else { s3; s4; }</code> bloğu bir modül müdür?","b":"<b>Hayır.</b> Bitişik ve sınır öğeleriyle çevrili ama <b>adı (aggregate identifier) yok</b>, ismiyle çağrılamaz. Metoda konup isim verilirse modül olur.","t":["kavram"]},{"id":"0313e5d4b0","f":"Bir modülün üç özelliği: <b>function, logic, context</b>. &quot;Newton algoritmasıyla double sayıların karekökünü hesaplayan modül&quot; için?","b":"<b>Function</b> (ne yapar): karekök hesaplar.<br><b>Logic</b> (nasıl): Newton algoritmasıyla.<br><b>Context</b> (ne üzerinde): double precision sayılar.","t":["kavram","cikmis"]},{"id":"09b6e101c0","f":"Bilgisayar tasarımı örneği: kapı türüne göre çiplere bölmek (Tasarım 2) neden kötü?","b":"İşlevsel olarak eşdeğer ama: anlaşılması zor, hatanın yerini bulmak zor, genişletmesi zor, başka üründe yeniden kullanılamaz.<br>Ders: <b>maximal relationships within modules, minimal relationships between modules</b>.","t":["kavram"]},{"id":"7d2090c35e","f":"<b>Cohesion</b> nedir?","b":"Bir modülün <b>içindeki</b> etkileşimin derecesi. <b>Yüksek</b> olmalı.<div style='text-align:left'><i>EN:</i> <i>Cohesion is the degree of interaction within a module.</i></div>","t":["tanim","cikmis","hoca_sorar"]},{"id":"4682b06dba","f":"<b>Coupling</b> nedir?","b":"<b>İki modül arasındaki</b> etkileşimin derecesi. <b>Düşük</b> olmalı.<div style='text-align:left'><i>EN:</i> <i>Coupling is the degree of interaction between two modules.</i></div>","t":["tanim","cikmis","hoca_sorar"]},{"id":"19df0bebd7","f":"Which one yields a <b>robust architecture</b>?<br>a) Loose coupling / high cohesion b) High coupling / high cohesion c) Low coupling / low cohesion d) Tight coupling e) Loose coupling / low cohesion","b":"<b>a) Loose (low) coupling / high cohesion</b>.","t":["cikmis","test"]},{"id":"a23af7c2d9","f":"Cohesion'ın <b>7 seviyesi</b> (en kötüden en iyiye)?","b":"<ol style='text-align:left'><li>Coincidental</li><li>Logical</li><li>Temporal</li><li>Procedural</li><li>Communicational</li><li>Functional</li><li>Informational</li></ol><div style='color:#888;font-size:0.85em'>💡 &quot;Can Leyla Tatilde Pazar Cuma Fransa'ya İner&quot; — C-L-T-P-C-F-I. Ölçek doğrusal değil.</div>","t":["liste","cikmis","hoca_sorar","ezber"]},{"id":"5b299224ea","f":"Coupling'in <b>5 seviyesi</b> (en kötüden en iyiye)?","b":"<ol style='text-align:left'><li>Content</li><li>Common</li><li>Control</li><li>Stamp</li><li>Data</li></ol><div style='color:#888;font-size:0.85em'>💡 &quot;Cem Can Cuma Sabah Dans etti&quot; — C-C-C-S-D (Content, Common, Control, Stamp, Data).</div>","t":["liste","cikmis","hoca_sorar","ezber"]},{"id":"e1cdbdd19c","f":"En kötü ve en iyi cohesion? En kötü ve en iyi coupling?","b":"Cohesion: en kötü <b>coincidental</b>, en iyi <b>informational</b> (sonra functional).<br>Coupling: en kötü <b>content</b>, en iyi <b>data</b>.","t":["ezber"]},{"id":"76d55bb7f1","f":"<b>Coincidental cohesion</b>: tanım, neden oluşur, neden kötü, düzeltme?","b":"Modül <b>birbiriyle tamamen ilgisiz</b> birden çok eylem yapar.<br>Nasıl oluşur: &quot;her modül 35–50 satır olsun&quot; gibi kurallar.<br>Kötü: bakımı zor, <b>yeniden kullanılamaz</b>.<br>Düzeltme: her biri tek iş yapan modüllere böl (Single Responsibility).<div style='text-align:left'><i>EN:</i> <i>The module performs multiple, completely unrelated actions.</i></div>","t":["tanim","cohesion"]},{"id":"f6d5637db6","f":"<b>Logical cohesion</b>: tanım?","b":"Modül <b>birbiriyle ilgili</b> bir dizi eylem yapar; <b>hangisinin çalışacağını çağıran modül seçer</b> (opCode / flag / switch).<div style='text-align:left'><i>EN:</i> <i>The module performs a series of related actions, one of which is selected by the calling module.</i></div>","t":["tanim","cohesion","cikmis"]},{"id":"05e2f4da63","f":"Logical cohesion neden kötü? (3 sebep + OCP)","b":"<ol style='text-align:left'><li><b>Arayüz anlaşılması zor</b> (hangi opCode'da hangi parametre?)</li><li>Eylemlerin kodu <b>iç içe geçebilir</b> (intertwined)</li><li>Yeniden kullanmak zor</li></ol>Hoca: yeni yazıcı için <code>if (opCode == 38)</code> eklemek → <b>Open-Closed</b> ihlali.","t":["cohesion"]},{"id":"ffb7afb761","f":"Logical cohesion nasıl düzeltilir?","b":"Her eylemi kendi metoduna ayır (<b>functional</b>); çağıran doğrudan ilgili metodu çağırsın. OO çözüm: ortak arayüz (ör. <code>IRapor</code>) + her durum için ayrı sınıf (<b>polymorphism</b>); yeni durum eklemek mevcut kodu değiştirmez.","t":["cohesion","duzeltme"]},{"id":"090cfdba85","f":"<b>Temporal cohesion</b>: tanım, örnek, neden kötü?","b":"Modül <b>zaman açısından ilişkili</b> eylemler yapar; sadece aynı anda/art arda yapıldıkları için bir aradalar (başlatma, kapanış).<br>Örnek: <i>perform_initialization</i> (dosyaları aç, tabloyu sıfırla, ilk kaydı oku).<br>Kötü: eylemler birbirleriyle <b>zayıf</b>, başka modüllerdeki eylemlerle <b>güçlü</b> ilişkili; yeniden kullanılamaz.<div style='text-align:left'><i>EN:</i> <i>The module performs a series of actions related in time.</i></div>","t":["tanim","cohesion"]},{"id":"2997890b4b","f":"Temporal cohesion nasıl düzeltilir?","b":"Her başlatma/kapanış işini ilgili sınıfa taşı (tablo başlatma → tablo sınıfının constructor'ı, dosya açma → dosya sınıfı).","t":["cohesion","duzeltme"]},{"id":"507c7c2527","f":"<b>Procedural cohesion</b>: tanım ve örnek?","b":"Modül <b>ürünün izlediği prosedürle (iş akışındaki sırayla)</b> ilişkili eylemler yapar; eylemler <b>farklı veriler</b> üzerinde.<br>Örnek: <i>read_part_number_and_update_repair_record_on_master_file</i>.<div style='text-align:left'><i>EN:</i> <i>The module performs a series of actions related by the procedure to be followed by the product.</i></div>","t":["tanim","cohesion"]},{"id":"720b7fee6c","f":"<b>Communicational cohesion</b>: tanım ve örnek?","b":"Procedural + <b>bütün eylemler aynı veri üzerinde</b> çalışır.<br>Örnek: <i>update_record_in_database_and_write_it_to_audit_trail</i>, <i>calculate_new_coordinates_and_send_them_to_terminal</i>.<div style='text-align:left'><i>EN:</i> <i>The actions are related by the procedure of the product and all of them are performed on the same data.</i></div>","t":["tanim","cohesion"]},{"id":"ef32112e81","f":"Procedural ile communicational cohesion arasındaki <b>tek fark</b>?","b":"İkisinde de eylemler ürünün prosedürüne göre art arda. <b>Communicational</b>'da hepsi <b>aynı veri</b> üzerinde; procedural'da farklı veriler.","t":["karsilastirma","cohesion"]},{"id":"ef39496117","f":"Communicational cohesion neden hâlâ kötü? Hocanın Lego benzetmesi?","b":"Hâlâ birden fazla iş yapar, yeniden kullanılabilirlik düşük.<br>Lego: 5 birimlik Lego'yu sadece 5 birime ihtiyaç olunca kullanırsın; 1 birimlik Lego her yerde kullanılır. Modül tek iş yaptıkça yeniden kullanılabilir.","t":["cohesion"]},{"id":"14de80cd37","f":"<b>Functional cohesion</b>: tanım, örnek, avantajlar?","b":"Modül <b>tam olarak tek bir eylem</b> yapar.<br>Örnek: <i>get_temperature_of_furnace</i>, <i>calculate_sales_commission</i>.<br>Avantajlar: <b>yeniden kullanılabilir</b>, hata izolasyonu (corrective bakım kolay, az regression fault), genişletmesi kolay.<div style='text-align:left'><i>EN:</i> <i>The module performs exactly one action.</i></div>","t":["tanim","cohesion"]},{"id":"a623a77dd2","f":"<b>Informational cohesion</b>: tanım?","b":"Modül bir dizi eylem yapar; <b>her eylemin kendi giriş noktası (entry point)</b> ve <b>bağımsız kodu</b> vardır ve <b>hepsi aynı veri yapısı</b> üzerinde çalışır. Özünde bir <b>abstract data type</b>; <b>sınıflar</b> informational cohesion örneğidir.<div style='text-align:left'><i>EN:</i> <i>The module performs a number of actions, each with its own entry point and independent code, all performed on the same data structure.</i></div>","t":["tanim","cohesion"]},{"id":"f7b1ed1dae","f":"Cohesion türünü bulma algoritması (sınavda koddan tür bulma)?","b":"<ol style='text-align:left'><li>Tek eylem mi? → <b>Functional</b></li><li>Ayrı giriş noktalı eylemler, aynı gizli veri (sınıf/ADT)? → <b>Informational</b></li><li>Eylemler tamamen ilgisiz mi? → <b>Coincidental</b></li><li>Dışarıdan gelen kod/bayrakla biri mi seçiliyor? → <b>Logical</b></li><li>Sadece aynı zamanda yapıldıkları için mi bir arada? → <b>Temporal</b></li><li>İş akışında art arda adımlar mı? Aynı veri → <b>Communicational</b>; farklı veri → <b>Procedural</b></li></ol>","t":["algoritma","kod"]},{"id":"92aa53bd76","f":"Cohesion/coupling sorusunda cevapta mutlaka hangi 4 şey yazılmalı?","b":"<ol style='text-align:left'><li><b>Tür adı</b></li><li><b>Gerekçe</b> (neden o tür, tanıma dayanarak)</li><li><b>Düzeltilmiş kod</b></li><li><b>Yeni seviye</b> (&quot;after refactoring each method has functional cohesion&quot;)</li></ol>","t":["cikmis","sinav_taktigi"]},{"id":"34a5329af7","f":"<b>Content coupling</b>: tanım ve örnekler?","b":"Bir modül <b>diğerinin içeriğine doğrudan başvurur</b>: p, q'nun bir komutunu değiştirir; q'nun yerel verisine displacement ile erişir; q'daki bir yerel etikete dallanır (<code>goto</code>).<br>Kötü: q'daki neredeyse her değişiklik (yeni derleyici bile) p'yi de değiştirir.<div style='text-align:left'><i>EN:</i> <i>One module directly references the contents of the other.</i></div>","t":["tanim","coupling"]},{"id":"7f17144a54","f":"<b>Common coupling</b>: tanım ve örnekler?","b":"İki modül <b>aynı global veriye</b> (yazma) erişimine sahip: aynı global değişken, aynı DB kaydı, FORTRAN <code>common</code>, C# <code>public static</code> alan.<div style='text-align:left'><i>EN:</i> <i>Both modules have write access to the same global data.</i></div>","t":["tanim","coupling"]},{"id":"5fb15dbd1d","f":"Common coupling neden kötü?","b":"<ul style='text-align:left'><li>Kod okunamaz; <b>yan etkiler</b>: modülü anlamak için global değişkeni değiştiren bütün modülleri okumak gerekir</li><li>Global bildirimi değişince diğer modüller de değişmeli</li><li>Yeniden kullanmak zor</li><li><b>Clandestine</b> common coupling: p'yi hiç değiştirmeden p ile ürün arasındaki bağ değişebilir</li><li>Modül gereğinden fazla veriye maruz kalır → <b>bilgisayar suçu</b> riski</li></ul>","t":["coupling"]},{"id":"6b9f057e6c","f":"Common coupling nasıl düzeltilir?","b":"Global değişkeni kaldır; veriyi <b>parametreyle</b> gönder (data coupling) ya da veriyi ve onu değiştiren işlemleri bir <b>sınıfa kapsülle</b> (information hiding).","t":["coupling","duzeltme"]},{"id":"075d2ba33e","f":"<b>Control coupling</b>: tanım?","b":"Bir modül diğerine bir <b>kontrol öğesi</b> (flag, opCode, switch) gönderir: <b>çağrılanın ne yapacağını çağıran belirler</b>. Genellikle <b>logical cohesion</b>'lı bir modüle opCode göndermekle birlikte görülür.<div style='text-align:left'><i>EN:</i> <i>One module passes an element of control to the other; it explicitly controls the logic of the other.</i></div>","t":["tanim","coupling"]},{"id":"df3db2ad79","f":"Kitaptaki ayrım: q, p'ye &quot;başaramadım&quot; derse bu veri mi kontrol mü? &quot;başaramadım, ABC123 hata mesajını yaz&quot; derse?","b":"&quot;Başaramadım&quot; → <b>veri</b>.<br>&quot;Başaramadım, ABC123 mesajını yaz&quot; → <b>kontrol</b> (q, p'nin ne yapacağını belirliyor).","t":["coupling"]},{"id":"0764c680ba","f":"Control coupling neden kötü, nasıl düzeltilir?","b":"Modüller bağımsız değil: çağıran, çağrılanın iç mantığını bilmek zorunda; reuse azalır.<br>Düzeltme: her görevi ayrı metot yap, çağıran doğrudan <code>Gorev3()</code>'ü çağırsın.","t":["coupling","duzeltme"]},{"id":"5a06051492","f":"<b>Stamp coupling</b>: tanım?","b":"Parametre olarak bir <b>veri yapısı</b> gönderilir ama çağrılan modül yapının <b>yalnızca bazı</b> bileşenlerini kullanır. Örnek: <i>calculate_withholding(employee_record)</i>.<br>Hoca: sadece struct değil, <b>dizi</b> gönderilip bazı elemanları kullanılıyorsa da stamp.<div style='text-align:left'><i>EN:</i> <i>A data structure is passed as an argument, but the called module operates on only some of the individual components.</i></div>","t":["tanim","coupling","cikmis"]},{"id":"1b81930725","f":"Stamp coupling neden kötü? Hocanın şifre örneği?","b":"Hangi alanların kullanıldığı modül okunmadan anlaşılmaz; reuse zor; <b>gereğinden fazla veri</b> geçer → kontrolsüz erişim, <b>bilgisayar suçu</b>.<br>Hoca: &quot;kullanmadığı hâlde şifreyi gönderiyorsunuz, o modüle şifre yetkisi veriyorsunuz.&quot;","t":["coupling"]},{"id":"4acf952420","f":"Veri yapısı göndermek her zaman stamp coupling midir?","b":"Hayır. Yapının <b>bütün</b> bileşenleri kullanılıyorsa <b>data coupling</b>'dir: <i>invert_matrix(original, inverted)</i>, <i>print_inventory_record(warehouse_record)</i>.","t":["coupling"]},{"id":"0bbddde7c6","f":"<b>Data coupling</b>: tanım ve örnek?","b":"Bütün parametreler <b>homojen veri öğeleri</b>: basit parametreler ya da <b>bütün elemanları kullanılan</b> veri yapıları.<br>Örnek: <i>display_time_of_arrival(flight_number)</i>, <i>compute_product(a, b)</i>. Bakımı en kolay.<div style='text-align:left'><i>EN:</i> <i>Every argument is either a simple argument or a data structure in which all elements are used by the called module.</i></div>","t":["tanim","coupling"]},{"id":"915cad0b76","f":"Coupling türünü bulma algoritması?","b":"<ol style='text-align:left'><li>Diğerinin kodunu/etiketini/yerel verisini değiştiriyor ya da içine dallanıyor mu? → <b>Content</b></li><li>Aynı global veriyi (static alan, global değişken, aynı DB kaydı) yazıp okuyorlar mı? → <b>Common</b></li><li>Gönderilen parametre ne yapılacağını belirleyen bayrak/kod mu? → <b>Control</b></li><li>Struct/kayıt/dizi gönderiliyor ama bir kısmı mı kullanılıyor? → <b>Stamp</b></li><li>Hepsi basit veri ya da tamamen kullanılan yapı mı? → <b>Data</b></li></ol>","t":["algoritma","kod"]},{"id":"e012190b86","f":"Cohesion türü?<pre style='text-align:left;font-size:0.85em'>void metot2(int opCode)<br>{<br>    if (opCode == 3)      PrintLocalSalesReport();<br>    else if (opCode == 4) PrintRegionalSalesReport();<br>    else if (opCode == 5) PrintNationalSalesReport();<br>    else                  PrintInternationalSalesReport();<br>}</pre>","b":"<b>Logical cohesion</b> — ilgili eylemlerden biri çağıranın gönderdiği <code>opCode</code> ile seçiliyor. Çağıranla arasında <b>control coupling</b>.","t":["kod","cikmis","test"]},{"id":"f674c24c40","f":"metot1 ile metot2 arasındaki coupling türü?<pre style='text-align:left;font-size:0.85em'>void metot1()<br>{<br>    int[] a = new int[10];<br>    for (int i = 0; i &lt; 10; i++) a[i] = i * i;<br>    Console.WriteLine(metot2(a));<br>}<br>int metot2(int[] dizi) { return dizi[0] + dizi[9]; }</pre>","b":"<b>Stamp coupling</b> — dizi gönderiliyor ama sadece <code>dizi[0]</code> ve <code>dizi[9]</code> kullanılıyor.<br>Düzeltme: <code>int metot2(int ilk, int son)</code> → data coupling.","t":["kod","cikmis","test"]},{"id":"41e2939383","f":"Cohesion türü ve düzeltme? (2025–26 vizesi)<pre style='text-align:left;font-size:0.85em'>class Siparis<br>{<br>    public double toplamTutar;<br>    public void kdvekle_indirimuygula(int indirimOrani)<br>    {<br>        toplamTutar = toplamTutar - toplamTutar * indirimOrani / 100.0;<br>        toplamTutar = toplamTutar + toplamTutar * 0.20;<br>    }<br>}</pre>","b":"<b>Communicational cohesion</b>: iki eylem (indirim, KDV), prosedüre göre art arda ve <b>ikisi de aynı veri</b> (<code>toplamTutar</code>) üzerinde.<br>Düzeltme: <code>private</code> alan + <code>IndirimUygula(int)</code> ve <code>KdvEkle(double)</code> ayrı metotlar → metotlar <b>functional</b>, sınıf <b>informational</b>, parametreler <b>data coupling</b>.<div style='text-align:left'><i>EN:</i> <i>It has communicational cohesion because it performs two actions related by the procedure of the product and both operate on the same data.</i></div>","t":["kod","cikmis"]},{"id":"a150cf3403","f":"Cohesion türü? (2025–26 vizesindeki ikinci metot)<pre style='text-align:left;font-size:0.85em'>public void Islemler(Musteri m, double faizOrani)<br>{<br>    double faiz = faizOrani / 100;<br>    Console.WriteLine(&quot;Hos geldiniz &quot; + m.Ad);<br>    m.Bakiye = m.Bakiye + m.Bakiye * faiz;<br>    LogDosyasiniAc();<br>}</pre>","b":"<b>Coincidental cohesion</b> — faiz hesabı, karşılama mesajı ve log açma birbiriyle ilgisiz (oturum başında art arda yapılıyorsa <i>temporal</i> da savunulabilir).<br>Ayrıca bütün <code>Musteri</code> gönderilip sadece Ad ve Bakiye kullanıldığı için çağıranla <b>stamp coupling</b>.","t":["kod","cikmis"]},{"id":"4b51b42270","f":"<code>public static double toplamTutar;</code> alanını birden çok metot okuyup yazıyorsa aralarında hangi coupling?","b":"<b>Common coupling</b> (aynı global veriye yazma erişimi).","t":["kod","cikmis"]},{"id":"0e246e9cae","f":"Cohesion türü?<pre style='text-align:left;font-size:0.85em'>void SistemKapat()<br>{<br>    log.Kapat();<br>    ekran.Temizle();<br>    yedek.Al();<br>}</pre>","b":"<b>Temporal cohesion</b> — işler birbirinden bağımsız, sadece kapanış anında art arda yapıldıkları için bir arada.","t":["kod","alistirma"]},{"id":"945a2b5c98","f":"Cohesion ve coupling türü?<pre style='text-align:left;font-size:0.85em'>void Hesapla(char islem, double a, double b)<br>{<br>    if (islem == &#x27;+&#x27;) Console.WriteLine(a + b);<br>    else if (islem == &#x27;-&#x27;) Console.WriteLine(a - b);<br>    else if (islem == &#x27;*&#x27;) Console.WriteLine(a * b);<br>}</pre>","b":"<b>Logical cohesion</b>; çağıranla <b>control coupling</b> (<code>islem</code> kontrol öğesi). OCP ihlali.<br>Düzeltme: <code>Topla(a,b)</code>, <code>Cikar</code>, <code>Carp</code> ayrı metotlar (functional + data coupling) ya da <code>IIslem</code> arayüzü.","t":["kod","alistirma"]},{"id":"4aee785596","f":"Cohesion ve coupling?<pre style='text-align:left;font-size:0.85em'>class Ogrenci { public string No, Ad, Soyad, Sifre; public double Ortalama; }<br>bool BursAlirMi(Ogrenci o) { return o.Ortalama &gt;= 3.0; }</pre>","b":"<code>BursAlirMi</code> <b>functional</b>; çağıranla <b>stamp coupling</b> (bütün kayıt, şifre dahil, gidiyor; sadece Ortalama kullanılıyor).<br>Düzeltme: <code>bool BursAlirMi(double ortalama)</code> → data coupling.","t":["kod","alistirma"]},{"id":"b5b5f38b3a","f":"Coupling türü?<pre style='text-align:left;font-size:0.85em'>static class Durum { public static bool indirimVar; }<br>void KampanyaBaslat() { Durum.indirimVar = true; }<br>double FiyatHesapla(double f) { return Durum.indirimVar ? f * 0.9 : f; }</pre>","b":"<b>Common coupling</b> — iki metot aynı global veriyi yazıp okuyor.<br>Düzeltme: <code>FiyatHesapla(double f, double indirimOrani)</code> (data coupling) ya da bir <code>Kampanya</code> sınıfında kapsülle.","t":["kod","alistirma"]},{"id":"290813bdf5","f":"Cohesion türü?<pre style='text-align:left;font-size:0.85em'>void NotGirVeOrtalamaGuncelle(Ogrenci o, int not)<br>{<br>    o.Notlar.Add(not);<br>    o.Ortalama = o.Notlar.Average();<br>}</pre>","b":"<b>Communicational cohesion</b> — iki iş, prosedürle ilişkili ve aynı veri (<code>o</code>) üzerinde.<br>Daha iyisi: Ogrenci sınıfına <code>NotEkle(int)</code> ve <code>Ortalama()</code>.","t":["kod","alistirma"]},{"id":"99fe4ea9d6","f":"Cohesion türü?<pre style='text-align:left;font-size:0.85em'>class Kuyruk<br>{<br>    private int[] d = new int[100]; private int bas, son;<br>    public void Ekle(int x) { d[son++] = x; }<br>    public int Cikar() { return d[bas++]; }<br>    public bool BosMu() { return bas == son; }<br>}</pre>","b":"<b>Informational cohesion</b> — her işlemin kendi giriş noktası ve bağımsız kodu var, hepsi aynı gizli veri yapısı üzerinde (ADT). Düzeltme gerekmez.","t":["kod","alistirma"]},{"id":"90bd3288ba","f":"Cohesion türü?<pre style='text-align:left;font-size:0.85em'>void ParcaNoOkuVeTamirKaydiGuncelle()<br>{<br>    int parcaNo = int.Parse(Console.ReadLine());<br>    TamirKaydi k = anaDosya.Bul(parcaNo);<br>    k.TamirSayisi++;<br>    anaDosya.Guncelle(k);<br>}</pre>","b":"<b>Procedural cohesion</b> — iş akışında art arda gelen adımlar ama <b>farklı veriler</b> (parça numarası, tamir kaydı).<br>Düzeltme: <code>ParcaNoOku()</code> ve <code>TamirKaydiGuncelle(int)</code>.","t":["kod","alistirma"]},{"id":"5de58746ea","f":"Hocanın 2025 dersindeki kod: türler?<pre style='text-align:left;font-size:0.85em'>if (isDoc) UsePrinter(&quot;network&quot;);<br>else       UsePdfWriter(new int[] {1, 2, 3, 4, 5});<br><br>void UsePrinter(string b)  { Console.WriteLine(b); }<br>void UsePdfWriter(int[] a) { Console.WriteLine(a[0] + a[a.Length-1]); }<br>void WriteTimePrint()      { Console.WriteLine(DateTime.Now); Print(true); }</pre>","b":"<ul style='text-align:left'><li><code>UsePrinter</code>, <code>UsePdfWriter</code>: <b>functional</b></li><li><code>WriteTimePrint</code>: <b>coincidental ya da temporal</b> (hoca ikisini de kabul etti)</li><li>Bayrağa göre seçen kısım: <b>logical</b>; bayrağı gönderenle <b>control coupling</b></li><li><code>UsePdfWriter</code>'a bütün dizi, sadece ilk/son kullanılıyor → <b>stamp coupling</b></li><li><code>UsePrinter(&quot;network&quot;)</code> → <b>data coupling</b></li></ul>","t":["kod","cikmis"]},{"id":"57e6beede6","f":"Hafta 5 sıcaklık örnekleri: &quot;edit site, time, <b>or</b> temperature field&quot; modülünün cohesion'ı? &quot;initialize sums and open files&quot;?","b":"edit … or … → <b>Logical</b> (birden çok işlemden biri seçiliyor).<br>initialize sums and open files → <b>Coincidental</b> (zamana bağlı görülürse temporal).","t":["cikmis","ornek"]},{"id":"2d911b6e2f","f":"Kod: modül M1 içinde <code>goto BB;</code>, BB etiketi M2'nin içinde. Coupling?","b":"<b>Content coupling</b> — M1, M2'nin içindeki yerel etikete dallanıyor.","t":["kod"]},{"id":"8c3a45091c","f":"<b>Data encapsulation</b> nedir? İş kuyruğu örneğinde iki tasarım?","b":"Bir veri yapısı + o veri yapısı üzerinde yapılan işlemler bir arada.<br>Tasarım 1: kuyruk işlemleri her yere dağılmış → düşük cohesion. Tasarım 2: <code>job_queue</code> + initialize/add/delete bir modülde → <b>informational cohesion</b>.","t":["tanim"]},{"id":"b46f83a31f","f":"Data encapsulation'ın geliştirme ve bakım açısından avantajı?","b":"<b>Geliştirme:</b> <b>abstraction</b> örneği — önce üst düzey kavramlarla tasarla, gerçekleştirmeyi önemseme; sonra alt düzeyi.<br><b>Bakım:</b> değişmesi muhtemel yerleri gizle; kuyruk bağlı listeye çevrilse bile kullanan modüller değişmez, sadece yeniden derlenir.","t":["kavram"]},{"id":"a8db71a18b","f":"<b>Abstraction</b> nedir? (hocanın tanımı)","b":"Gereksiz ayrıntıyı gizleyip ilgili ayrıntıyı vurgulayarak problemi üst düzeyde düşünmek (stepwise refinement aracı).","t":["tanim","cikmis"]},{"id":"45af675b67","f":"<b>Abstract data type (ADT)</b> nedir?","b":"Bir <b>veri tipi</b> + o tipin örnekleri üzerinde yapılan <b>işlemler</b>. Informational cohesion'a sahip veri tipidir; <b>sınıflar ADT örneğidir</b>.","t":["tanim","cikmis"]},{"id":"25e7677dad","f":"<b>Data abstraction</b> ile <b>procedural abstraction</b> farkı?","b":"<b>Data abstraction:</b> tasarımcı ADT düzeyinde düşünür.<br><b>Procedural abstraction:</b> bir prosedür tanımlamak = dili genişletmek.<br>İkisi de <b>information hiding</b>'in örneğidir.","t":["karsilastirma"]},{"id":"f99fc66860","f":"<b>Information hiding</b> nedir? C#'ta nasıl sağlanır?","b":"Modülleri, <b>değişmesi muhtemel öğeler gizlenecek</b> şekilde tasarlamak; gelecekteki değişiklik yerelleşir. C#: <code>private</code> alanlar, <code>public</code> metot/property (en az yetki). Public alanlar bunu bozar.<div style='text-align:left'><i>EN:</i> <i>Designing modules so that items likely to change are hidden; future change is localized.</i></div>","t":["tanim","cikmis"]},{"id":"2b62afb5a1","f":"<b>Class</b> nedir? (ADT ile ilişkisi)","b":"<b>Kalıtımı destekleyen</b> abstract data type.","t":["tanim"]},{"id":"a3c29cced3","f":"<b>Polymorphism</b> ve <b>dynamic binding</b> nedir? <code>myFile.open()</code> örneği?","b":"Klasikte <i>open_disk_file</i>, <i>open_tape_file</i>… açıkça seçilir. OO'da <code>myFile.open()</code> yazılır; hangi <code>open</code>'ın çalışacağı <b>çalışma zamanında</b> nesnenin sınıfına göre belirlenir (<b>dynamic binding</b>); aynı metot farklı sınıfların nesnelerine uygulanır (<b>polymorphism</b>).","t":["tanim","cikmis"]},{"id":"7a293cac72","f":"Polymorphism ve dynamic binding neden zayıf yan da olabilir?","b":"Bir metodun birden çok olası sürümü varsa kodu anlamak zorlaşır, bakım olumsuz etkilenebilir.","t":["kavram"]},{"id":"8d0fa0a574","f":"<b>Fragile base class problem</b> nedir?","b":"Taban sınıftaki bir değişikliğin <b>bütün alt sınıflara dalga gibi yayılması</b>. Sınıflar baştan dikkatle tasarlanmalı.","t":["tanim"]},{"id":"6649e6b98d","f":"OO paradigmanın zayıf yanları?","b":"<ul style='text-align:left'><li>Geliştirme eforu/boyut büyük olabilir (özellikle GUI)</li><li><b>Fragile base class</b></li><li>Alt sınıflar her şeyi miras alır, şişer → &quot;Use inheritance where appropriate&quot;</li><li>Polymorphism/dynamic binding sorun çıkarabilir</li><li>Kötü OO kod yazmak çok kolay</li></ul>","t":["liste"]},{"id":"bdc68982f0","f":"SOLID harfleri?","b":"<ol style='text-align:left'><li><b>S</b>ingle Responsibility</li><li><b>O</b>pen-Closed</li><li><b>L</b>iskov Substitution</li><li><b>I</b>nterface Segregation</li><li><b>D</b>ependency Inversion</li></ol>","t":["liste","solid"]},{"id":"0a94ff81f2","f":"Hangi SOLID ilkesi coincidental / procedural / communicational modülleri bölmeyi söyler?","b":"<b>Single Responsibility</b>: bir modülün değişmek için tek nedeni olmalı (tek iş) → functional cohesion.","t":["solid"]},{"id":"06043bf239","f":"Logical cohesion'da yeni durum için <code>if</code> eklemek hangi SOLID ilkesini ihlal eder?","b":"<b>Open-Closed</b>: genişletmeye açık, değişikliğe kapalı olmalı. Çözüm: arayüz + polymorphism.","t":["solid"]},{"id":"9d2dee2206","f":"Interface Segregation hangi coupling türüne benzer?","b":"<b>Stamp coupling</b>'e: sınıf, kullanmadığı şeylere (büyük arayüz) bağımlı olmamalı.","t":["solid"]}]},{"id":"d05","no":"5","ad":"ISO 25010","renk":"#FBBF24","konu":"konu-05-iso25010","kartlar":[{"id":"5cd3aa2834","f":"<b>Functional Suitability</b><br>Alt karakteristikleri nelerdir? (3)","b":"1. Functional completeness<br>2. Functional correctness<br>3. Functional appropriateness","t":["karakteristik->alt"]},{"id":"9c5742c683","f":"<b>Performance Efficiency</b><br>Alt karakteristikleri nelerdir? (3)","b":"1. Time behaviour<br>2. Resource utilization<br>3. Capacity","t":["karakteristik->alt"]},{"id":"3da2447cc9","f":"<b>Compatibility</b><br>Alt karakteristikleri nelerdir? (2)","b":"1. Co-existence<br>2. Interoperability","t":["karakteristik->alt"]},{"id":"8905642ae4","f":"<b>Interaction Capability</b><br>Alt karakteristikleri nelerdir? (8)","b":"1. Appropriateness recognizability<br>2. Learnability<br>3. Operability<br>4. User error protection<br>5. User engagement<br>6. Inclusivity<br>7. User assistance<br>8. Self-descriptiveness","t":["karakteristik->alt"]},{"id":"34a18e4386","f":"<b>Reliability</b><br>Alt karakteristikleri nelerdir? (4)","b":"1. Faultlessness<br>2. Availability<br>3. Fault tolerance<br>4. Recoverability","t":["karakteristik->alt"]},{"id":"d64acd9fd8","f":"<b>Security</b><br>Alt karakteristikleri nelerdir? (6)","b":"1. Confidentiality<br>2. Integrity<br>3. Non-repudiation<br>4. Accountability<br>5. Authenticity<br>6. Resistance","t":["karakteristik->alt"]},{"id":"a456cd7664","f":"<b>Maintainability</b><br>Alt karakteristikleri nelerdir? (5)","b":"1. Modularity<br>2. Reusability<br>3. Analysability<br>4. Modifiability<br>5. Testability","t":["karakteristik->alt"]},{"id":"709d082d4a","f":"<b>Flexibility</b><br>Alt karakteristikleri nelerdir? (4)","b":"1. Adaptability<br>2. Scalability<br>3. Installability<br>4. Replaceability","t":["karakteristik->alt"]},{"id":"2929199cd7","f":"<b>Safety</b><br>Alt karakteristikleri nelerdir? (5)","b":"1. Operational constraint<br>2. Risk identification<br>3. Fail safe<br>4. Hazard warning<br>5. Safe integration","t":["karakteristik->alt"]},{"id":"b09252b140","f":"<b>Functional completeness</b><br>Hangi karakteristiğe aittir?","b":"1. Functional Suitability","t":["alt->karakteristik"]},{"id":"1e63262367","f":"<b>Functional correctness</b><br>Hangi karakteristiğe aittir?","b":"1. Functional Suitability","t":["alt->karakteristik"]},{"id":"565c597c3c","f":"<b>Functional appropriateness</b><br>Hangi karakteristiğe aittir?","b":"1. Functional Suitability","t":["alt->karakteristik"]},{"id":"ff5e22fe8d","f":"<b>Time behaviour</b><br>Hangi karakteristiğe aittir?","b":"2. Performance Efficiency","t":["alt->karakteristik"]},{"id":"61c0dcc010","f":"<b>Resource utilization</b><br>Hangi karakteristiğe aittir?","b":"2. Performance Efficiency","t":["alt->karakteristik"]},{"id":"5dce4964fa","f":"<b>Capacity</b><br>Hangi karakteristiğe aittir?","b":"2. Performance Efficiency","t":["alt->karakteristik"]},{"id":"03ee1611cf","f":"<b>Co-existence</b><br>Hangi karakteristiğe aittir?","b":"3. Compatibility","t":["alt->karakteristik"]},{"id":"d6044e32ef","f":"<b>Interoperability</b><br>Hangi karakteristiğe aittir?","b":"3. Compatibility","t":["alt->karakteristik"]},{"id":"b3cc5a278f","f":"<b>Appropriateness recognizability</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"73ab52aaf2","f":"<b>Learnability</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"b5e363cd68","f":"<b>Operability</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"1749047e13","f":"<b>User error protection</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"7b0f789e62","f":"<b>User engagement</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"2c91145edb","f":"<b>Inclusivity</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"225023d9b5","f":"<b>User assistance</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"b21ac22e14","f":"<b>Self-descriptiveness</b><br>Hangi karakteristiğe aittir?","b":"4. Interaction Capability","t":["alt->karakteristik"]},{"id":"d6f30d0f85","f":"<b>Faultlessness</b><br>Hangi karakteristiğe aittir?","b":"5. Reliability","t":["alt->karakteristik"]},{"id":"c8c3d7c9e0","f":"<b>Availability</b><br>Hangi karakteristiğe aittir?","b":"5. Reliability","t":["alt->karakteristik"]},{"id":"69891a2d5f","f":"<b>Fault tolerance</b><br>Hangi karakteristiğe aittir?","b":"5. Reliability","t":["alt->karakteristik"]},{"id":"c254106b0d","f":"<b>Recoverability</b><br>Hangi karakteristiğe aittir?","b":"5. Reliability","t":["alt->karakteristik"]},{"id":"694318700a","f":"<b>Confidentiality</b><br>Hangi karakteristiğe aittir?","b":"6. Security","t":["alt->karakteristik"]},{"id":"eaaa3cb501","f":"<b>Integrity</b><br>Hangi karakteristiğe aittir?","b":"6. Security","t":["alt->karakteristik"]},{"id":"bec335ef45","f":"<b>Non-repudiation</b><br>Hangi karakteristiğe aittir?","b":"6. Security","t":["alt->karakteristik"]},{"id":"67d27dee17","f":"<b>Accountability</b><br>Hangi karakteristiğe aittir?","b":"6. Security","t":["alt->karakteristik"]},{"id":"b49c0ad25a","f":"<b>Authenticity</b><br>Hangi karakteristiğe aittir?","b":"6. Security","t":["alt->karakteristik"]},{"id":"025fdc26f8","f":"<b>Resistance</b><br>Hangi karakteristiğe aittir?","b":"6. Security","t":["alt->karakteristik"]},{"id":"24dc226b06","f":"<b>Modularity</b><br>Hangi karakteristiğe aittir?","b":"7. Maintainability","t":["alt->karakteristik"]},{"id":"cb88428c30","f":"<b>Reusability</b><br>Hangi karakteristiğe aittir?","b":"7. Maintainability","t":["alt->karakteristik"]},{"id":"ae3332d795","f":"<b>Analysability</b><br>Hangi karakteristiğe aittir?","b":"7. Maintainability","t":["alt->karakteristik"]},{"id":"20cd24bdf2","f":"<b>Modifiability</b><br>Hangi karakteristiğe aittir?","b":"7. Maintainability","t":["alt->karakteristik"]},{"id":"2306f8d08d","f":"<b>Testability</b><br>Hangi karakteristiğe aittir?","b":"7. Maintainability","t":["alt->karakteristik"]},{"id":"584f5968a4","f":"<b>Adaptability</b><br>Hangi karakteristiğe aittir?","b":"8. Flexibility","t":["alt->karakteristik"]},{"id":"8bf2312367","f":"<b>Scalability</b><br>Hangi karakteristiğe aittir?","b":"8. Flexibility","t":["alt->karakteristik"]},{"id":"171b972109","f":"<b>Installability</b><br>Hangi karakteristiğe aittir?","b":"8. Flexibility","t":["alt->karakteristik"]},{"id":"8b952daacf","f":"<b>Replaceability</b><br>Hangi karakteristiğe aittir?","b":"8. Flexibility","t":["alt->karakteristik"]},{"id":"0370aedd0d","f":"<b>Operational constraint</b><br>Hangi karakteristiğe aittir?","b":"9. Safety","t":["alt->karakteristik"]},{"id":"bb3e506e97","f":"<b>Risk identification</b><br>Hangi karakteristiğe aittir?","b":"9. Safety","t":["alt->karakteristik"]},{"id":"a2d2b98a8d","f":"<b>Fail safe</b><br>Hangi karakteristiğe aittir?","b":"9. Safety","t":["alt->karakteristik"]},{"id":"0c75633227","f":"<b>Hazard warning</b><br>Hangi karakteristiğe aittir?","b":"9. Safety","t":["alt->karakteristik"]},{"id":"653c210ef2","f":"<b>Safe integration</b><br>Hangi karakteristiğe aittir?","b":"9. Safety","t":["alt->karakteristik"]},{"id":"18cbd50bb6","f":"ISO 25010: <b>Functional completeness</b> ne anlama gelir?","b":"İşlevler belirtilen bütün görevleri ve kullanıcı hedeflerini kapsıyor mu?<br><span style='color:#888'>(Functional Suitability)</span>","t":["anlam"]},{"id":"7ce0fa6a51","f":"ISO 25010: <b>Functional correctness</b> ne anlama gelir?","b":"Doğru sonuçları gereken hassasiyetle üretiyor mu?<br><span style='color:#888'>(Functional Suitability)</span>","t":["anlam"]},{"id":"8bd6c9a899","f":"ISO 25010: <b>Functional appropriateness</b> ne anlama gelir?","b":"İşlevler görevlerin yerine getirilmesini kolaylaştırıyor mu?<br><span style='color:#888'>(Functional Suitability)</span>","t":["anlam"]},{"id":"aa596a2b45","f":"ISO 25010: <b>Time behaviour</b> ne anlama gelir?","b":"Yanıt ve işlem süreleri, verim (throughput) gereksinimleri karşılıyor mu?<br><span style='color:#888'>(Performance Efficiency)</span>","t":["anlam"]},{"id":"2d9bebe987","f":"ISO 25010: <b>Resource utilization</b> ne anlama gelir?","b":"Kullanılan kaynak (bellek, CPU) miktarı ve türü.<br><span style='color:#888'>(Performance Efficiency)</span>","t":["anlam"]},{"id":"50b12a7457","f":"ISO 25010: <b>Capacity</b> ne anlama gelir?","b":"Bir parametrenin üst sınırları (eşzamanlı kullanıcı, kayıt sayısı).<br><span style='color:#888'>(Performance Efficiency)</span>","t":["anlam"]},{"id":"c9345d25e6","f":"ISO 25010: <b>Co-existence</b> ne anlama gelir?","b":"Ortak ortam ve kaynakları başka ürünlerle zarar vermeden paylaşabilme.<br><span style='color:#888'>(Compatibility)</span>","t":["anlam"]},{"id":"ff3a9f92ea","f":"ISO 25010: <b>Interoperability</b> ne anlama gelir?","b":"İki veya daha fazla sistemin bilgi alışverişi yapıp bu bilgiyi kullanabilmesi (hoca: e-Devlet ile kimlik doğrulama).<br><span style='color:#888'>(Compatibility)</span>","t":["anlam"]},{"id":"f889a3cab7","f":"ISO 25010: <b>Appropriateness recognizability</b> ne anlama gelir?","b":"Kullanıcı ürünün ihtiyacına uygun olup olmadığını anlayabiliyor mu?<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"512ec8bdff","f":"ISO 25010: <b>Learnability</b> ne anlama gelir?","b":"Kullanmayı öğrenme kolaylığı.<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"a57e3825a9","f":"ISO 25010: <b>Operability</b> ne anlama gelir?","b":"Kullanma ve kontrol etme kolaylığı.<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"9e3dd44a57","f":"ISO 25010: <b>User error protection</b> ne anlama gelir?","b":"Kullanıcıyı hata yapmaktan koruma (hoca: numara kutusuna harf yazdırmamak; ilk düğmeye basılmadan ikinciyi pasif tutmak).<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"6fff6236c6","f":"ISO 25010: <b>User engagement</b> ne anlama gelir?","b":"Hoş, ilgi çekici, motive edici etkileşim (2011'de UI aesthetics).<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"1f702745bb","f":"ISO 25010: <b>Inclusivity</b> ne anlama gelir?","b":"Farklı özellik ve yeteneklerdeki insanların kullanabilmesi (2011'de Accessibility).<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"8d0f80192f","f":"ISO 25010: <b>User assistance</b> ne anlama gelir?","b":"Kullanıcıya yardım ve destek (yardım menüsü, ipuçları).<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"fff9fdd982","f":"ISO 25010: <b>Self-descriptiveness</b> ne anlama gelir?","b":"Ürünün kendini açıklaması; ekranın ne yapılacağını kendiliğinden göstermesi.<br><span style='color:#888'>(Interaction Capability)</span>","t":["anlam"]},{"id":"907496fa6b","f":"ISO 25010: <b>Faultlessness</b> ne anlama gelir?","b":"Normal çalışmada hatasız işleme (2011'de Maturity).<br><span style='color:#888'>(Reliability)</span>","t":["anlam"]},{"id":"02904b7bdb","f":"ISO 25010: <b>Availability</b> ne anlama gelir?","b":"Gerektiğinde çalışır ve erişilebilir olma.<br><span style='color:#888'>(Reliability)</span>","t":["anlam"]},{"id":"8b525b134d","f":"ISO 25010: <b>Fault tolerance</b> ne anlama gelir?","b":"Donanım/yazılım hatalarına rağmen amaçlandığı gibi çalışma.<br><span style='color:#888'>(Reliability)</span>","t":["anlam"]},{"id":"189c4d8063","f":"ISO 25010: <b>Recoverability</b> ne anlama gelir?","b":"Kesinti/arıza sonrası veriyi kurtarıp istenen duruma dönebilme.<br><span style='color:#888'>(Reliability)</span>","t":["anlam"]},{"id":"1dc761e3a6","f":"ISO 25010: <b>Confidentiality</b> ne anlama gelir?","b":"Veriye yalnızca yetkililerin erişmesi.<br><span style='color:#888'>(Security)</span>","t":["anlam"]},{"id":"1fd2ed2f49","f":"ISO 25010: <b>Integrity</b> ne anlama gelir?","b":"Program veya verinin yetkisiz erişim/değişikliğe karşı korunması.<br><span style='color:#888'>(Security)</span>","t":["anlam"]},{"id":"4ce4b28d1e","f":"ISO 25010: <b>Non-repudiation</b> ne anlama gelir?","b":"Eylem/olayların gerçekleştiğinin kanıtlanabilmesi, sonradan inkâr edilememesi.<br><span style='color:#888'>(Security)</span>","t":["anlam"]},{"id":"e1aad9053b","f":"ISO 25010: <b>Accountability</b> ne anlama gelir?","b":"Bir varlığın eylemlerinin tekil olarak o varlığa izlenebilmesi.<br><span style='color:#888'>(Security)</span>","t":["anlam"]},{"id":"fa6eb707a5","f":"ISO 25010: <b>Authenticity</b> ne anlama gelir?","b":"Bir özne veya kaynağın kimliğinin iddia edildiği gibi olduğunun kanıtlanması.<br><span style='color:#888'>(Security)</span>","t":["anlam"]},{"id":"5f894c668f","f":"ISO 25010: <b>Resistance</b> ne anlama gelir?","b":"Saldırılara karşı direnç (2023'te eklendi).<br><span style='color:#888'>(Security)</span>","t":["anlam"]},{"id":"4cc94abe99","f":"ISO 25010: <b>Modularity</b> ne anlama gelir?","b":"Bir bileşendeki değişikliğin diğerlerini en az etkileyecek şekilde ayrık bileşenlerden oluşma.<br><span style='color:#888'>(Maintainability)</span>","t":["anlam"]},{"id":"40e2a74315","f":"ISO 25010: <b>Reusability</b> ne anlama gelir?","b":"Bir varlığın birden fazla sistemde kullanılabilmesi.<br><span style='color:#888'>(Maintainability)</span>","t":["anlam"]},{"id":"5f84f5a6b4","f":"ISO 25010: <b>Analysability</b> ne anlama gelir?","b":"Değişikliğin etkisini değerlendirme, hata nedenini bulma, değişecek parçayı belirleme kolaylığı.<br><span style='color:#888'>(Maintainability)</span>","t":["anlam"]},{"id":"8abeb0eded","f":"ISO 25010: <b>Modifiability</b> ne anlama gelir?","b":"Hata eklemeden, kaliteyi düşürmeden değiştirilebilme.<br><span style='color:#888'>(Maintainability)</span>","t":["anlam"]},{"id":"ee6e4b44bf","f":"ISO 25010: <b>Testability</b> ne anlama gelir?","b":"Test kriterleri konup testlerin yapılabilmesi.<br><span style='color:#888'>(Maintainability)</span>","t":["anlam"]},{"id":"d5b29391c5","f":"ISO 25010: <b>Adaptability</b> ne anlama gelir?","b":"Farklı veya gelişen donanım, yazılım, ortama uyarlanabilme.<br><span style='color:#888'>(Flexibility)</span>","t":["anlam"]},{"id":"99d5a70ebb","f":"ISO 25010: <b>Scalability</b> ne anlama gelir?","b":"Artan/azalan iş yüküne göre ölçeklenebilme (2023'te eklendi).<br><span style='color:#888'>(Flexibility)</span>","t":["anlam"]},{"id":"6f79ab34b0","f":"ISO 25010: <b>Installability</b> ne anlama gelir?","b":"Belirli ortamda başarıyla kurulabilme / kaldırılabilme.<br><span style='color:#888'>(Flexibility)</span>","t":["anlam"]},{"id":"f20be67d0f","f":"ISO 25010: <b>Replaceability</b> ne anlama gelir?","b":"Aynı ortamda aynı amaçla başka bir ürünün yerine geçebilme.<br><span style='color:#888'>(Flexibility)</span>","t":["anlam"]},{"id":"d7865f0273","f":"ISO 25010: <b>Operational constraint</b> ne anlama gelir?","b":"Güvenli çalışma sınırları içinde kalma.<br><span style='color:#888'>(Safety)</span>","t":["anlam"]},{"id":"9ec1fc75b3","f":"ISO 25010: <b>Risk identification</b> ne anlama gelir?","b":"Riskleri belirleyebilme.<br><span style='color:#888'>(Safety)</span>","t":["anlam"]},{"id":"e73d779dba","f":"ISO 25010: <b>Fail safe</b> ne anlama gelir?","b":"Arıza anında kendini güvenli moda alma.<br><span style='color:#888'>(Safety)</span>","t":["anlam"]},{"id":"0a4386fe8f","f":"ISO 25010: <b>Hazard warning</b> ne anlama gelir?","b":"Tehlike durumunda uyarı verme.<br><span style='color:#888'>(Safety)</span>","t":["anlam"]},{"id":"6b01e756f0","f":"ISO 25010: <b>Safe integration</b> ne anlama gelir?","b":"Başka bileşenlerle güvenli bütünleşme.<br><span style='color:#888'>(Safety)</span>","t":["anlam"]},{"id":"6b4fb7be1a","f":"ISO 25010 karakteristiği <b>Functional Suitability</b> neyi ölçer?","b":"Ürün belirtilmiş ve örtük ihtiyaçları karşılayan işlevleri sağlıyor mu?","t":["anlam","karakteristik"]},{"id":"e11afad628","f":"ISO 25010 karakteristiği <b>Performance Efficiency</b> neyi ölçer?","b":"Kullanılan kaynağa göre performans.","t":["anlam","karakteristik"]},{"id":"5ef34ed313","f":"ISO 25010 karakteristiği <b>Compatibility</b> neyi ölçer?","b":"Başka ürünlerle bilgi alışverişi yapabilme / aynı ortamı paylaşabilme.","t":["anlam","karakteristik"]},{"id":"8fd56e79d7","f":"ISO 25010 karakteristiği <b>Interaction Capability</b> neyi ölçer?","b":"Belirli kullanıcıların ürünle etkileşebilme derecesi (2011'de Usability).","t":["anlam","karakteristik"]},{"id":"00de9c68a9","f":"ISO 25010 karakteristiği <b>Reliability</b> neyi ölçer?","b":"Belirtilen koşullarda, belirtilen süre boyunca belirtilen işlevleri yerine getirme.","t":["anlam","karakteristik"]},{"id":"70ab029d1c","f":"ISO 25010 karakteristiği <b>Security</b> neyi ölçer?","b":"Bilgi ve veriyi yetki düzeyine uygun şekilde koruma.","t":["anlam","karakteristik"]},{"id":"3c3e163628","f":"ISO 25010 karakteristiği <b>Maintainability</b> neyi ölçer?","b":"İyileştirmek, düzeltmek, uyarlamak için etkin biçimde değiştirilebilme.","t":["anlam","karakteristik"]},{"id":"22243c34f4","f":"ISO 25010 karakteristiği <b>Flexibility</b> neyi ölçer?","b":"Gereksinim, kullanım bağlamı ya da ortam değişikliklerine uyum (2011'de Portability).","t":["anlam","karakteristik"]},{"id":"75b0e47932","f":"ISO 25010 karakteristiği <b>Safety</b> neyi ölçer?","b":"İnsan hayatı, sağlık, mülk ve çevre için tehlike yaratmama (2023'te yeni).","t":["anlam","karakteristik"]},{"id":"2b15e958d8","f":"ISO/IEC 25010 (2023) <b>9 ana karakteristiğini</b> sırayla yaz.","b":"<ol style='text-align:left'><li>Functional Suitability</li><li>Performance Efficiency</li><li>Compatibility</li><li>Interaction Capability</li><li>Reliability</li><li>Security</li><li>Maintainability</li><li>Flexibility</li><li>Safety</li></ol><div style='color:#888;font-size:0.85em'>💡 FP-CIR-SMFS: &quot;Fonksiyonel Performans, Cihazlar İletişimde Rahat; Sistem Mutlaka Fazla Sağlam&quot;. Toplam 40 alt karakteristik.</div>","t":["liste","cikmis","hoca_sorar","ezber"]},{"id":"caf88525ab","f":"2025–26 vizesinde ISO sorusu nasıl puanlandı? Kaç alt başlık yazmalısın?","b":"18 puan: <b>ana başlık 1'er</b>, <b>alt başlık 0,5'er</b>. 9×1 + 18×0,5 = 18 → her ana başlıktan <b>en az 2</b> alt başlık. 2024–25'te tablonun tamamı istendi. Güvenli olan: hepsini yaz. Açıklama istenmiyor, maddeler yeterli.","t":["cikmis","sinav_taktigi"]},{"id":"a3760fbef0","f":"Which one is NOT an ISO/IEC 25010 quality characteristic?<br>a) Reliability b) Portability c) Compatibility d) Comprehensibility e) Security","b":"<b>d) Comprehensibility</b>. (Portability 2011 sürümünde vardı; 2023'te Flexibility oldu.)","t":["cikmis","test"]},{"id":"5fd179f18d","f":"ISO 25000 serisinin adı (SQuaRE açılımı)? ISO 25010 neyi tanımlar?","b":"<b>SQuaRE</b>: Systems and software Quality Requirements and Evaluation.<br>25010 → <b>kalite modelini</b>: ürün değerlendirilirken hangi kalite karakteristiklerinin dikkate alınacağını.","t":["tanim"]},{"id":"af40ad3a47","f":"Bir sistemin <b>kalitesi</b> nedir? (ISO 25010)","b":"Sistemin, paydaşlarının <b>belirtilmiş ve örtük ihtiyaçlarını</b> karşılama derecesi.","t":["tanim"]},{"id":"836ec4aaea","f":"Hocanın vurgusu: ISO 25010 karakteristikleri bir yazılımın ne yaptığını mı söyler?","b":"Hayır; <b>dokümanlarda nelerin tanımlanması gerektiğini</b> söyler. Ör. yanıt süresinin düşük/yüksek olması değil, <b>belgelerde tanımlanmış olması</b> önemlidir — tanımlıysa izlenebilir, ölçülebilir, iyileştirilebilir.","t":["kavram"]},{"id":"150520fe2a","f":"2011 sürümünde kaç karakteristik / alt karakteristik vardı? 2023'te?","b":"2011: <b>8</b> karakteristik, <b>31</b> alt.<br>2023: <b>9</b> karakteristik, <b>40</b> alt.","t":["sayi","karsilastirma"]},{"id":"c53ea8a7f9","f":"2011 → 2023 <b>isim değişiklikleri</b> (karakteristik düzeyinde)?","b":"<ul style='text-align:left'><li><b>Usability → Interaction Capability</b></li><li><b>Portability → Flexibility</b></li><li>Yeni karakteristik: <b>Safety</b></li></ul>","t":["karsilastirma"]},{"id":"069a224aa0","f":"2011 → 2023 <b>alt karakteristik</b> değişiklikleri?","b":"<ul style='text-align:left'><li>UI aesthetics → <b>User engagement</b></li><li>Accessibility → <b>Inclusivity</b></li><li>Yeni: <b>User assistance</b>, <b>Self-descriptiveness</b></li><li>Maturity → <b>Faultlessness</b></li><li>Security'ye yeni: <b>Resistance</b></li><li>Flexibility'ye yeni: <b>Scalability</b></li></ul>","t":["karsilastirma"]},{"id":"d9006446d2","f":"ISO 25010'da en çok alt karakteristiği olan karakteristik hangisi? En az olan?","b":"En çok: <b>Interaction Capability (8)</b>.<br>En az: <b>Compatibility (2)</b>.","t":["sayi","ezber"]},{"id":"151f9ec418","f":"Alt karakteristik sayılarını sırayla söyle (FS, PE, C, IC, R, Sec, M, F, Saf).","b":"3 – 3 – 2 – 8 – 4 – 6 – 5 – 4 – 5 = <b>40</b>","t":["sayi","ezber"]},{"id":"8df777000f","f":"Hem 2011 hem 2023'te aynı kalan, sınavda &quot;güvenli&quot; alt başlıklara örnek?","b":"Time behaviour, Co-existence, Interoperability, Learnability, Operability, Availability, Fault tolerance, Confidentiality, Integrity, Modularity, Testability, Installability, Adaptability…","t":["sinav_taktigi"]},{"id":"7ad2340f67","f":"Security'nin alt başlıklarını hatırlama ipucu?","b":"Confidentiality, Integrity (CIA'ya benzer) + Non-repudiation, Accountability, Authenticity, Resistance — &quot;inkâr edemezsin, hesabını verirsin, kim olduğunu kanıtlarsın, saldırıya dayanırsın&quot;.","t":["ezber"]},{"id":"3d1716e6a8","f":"Reliability'nin alt başlıklarını hatırlama ipucu?","b":"Hata olmasın (<b>faultlessness</b>), erişilebilsin (<b>availability</b>), hataya rağmen çalışsın (<b>fault tolerance</b>), sonra toparlansın (<b>recoverability</b>).","t":["ezber"]},{"id":"627e13e06b","f":"Senaryo: Sistem, sunuculardan biri çökse bile çalışmaya devam ediyor. Hangi alt karakteristik?","b":"<b>Fault tolerance</b> (Reliability).","t":["senaryo"]},{"id":"7eacbf5a56","f":"Senaryo: Kullanıcı, kendisinin yaptığı para transferini inkâr edemiyor çünkü işlem kaydı ve imza var. Hangi alt karakteristik?","b":"<b>Non-repudiation</b> (Security).","t":["senaryo"]},{"id":"bd557d778c","f":"Senaryo: Uygulama, e-Devlet ile kimlik bilgisi alışverişi yapıp kullanabiliyor. Hangi alt karakteristik?","b":"<b>Interoperability</b> (Compatibility).","t":["senaryo"]},{"id":"2f479e2f1f","f":"Senaryo: Kampanya günü kullanıcı sayısı 10 katına çıkınca sistem ek sunucularla yükü karşılıyor. Hangi alt karakteristik?","b":"<b>Scalability</b> (Flexibility).","t":["senaryo"]},{"id":"cc0545597a","f":"Senaryo: Form, telefon alanına harf girilmesine izin vermiyor. Hangi alt karakteristik?","b":"<b>User error protection</b> (Interaction Capability).","t":["senaryo"]},{"id":"40bea720a6","f":"Senaryo: Görme engelli kullanıcılar ekran okuyucuyla uygulamayı kullanabiliyor. Hangi alt karakteristik?","b":"<b>Inclusivity</b> (Interaction Capability; 2011'de Accessibility).","t":["senaryo"]},{"id":"d90aa67345","f":"Senaryo: Bir modülde değişiklik yapınca diğer modüller etkilenmiyor. Hangi alt karakteristik?","b":"<b>Modularity</b> (Maintainability).","t":["senaryo"]},{"id":"3f5532c094","f":"Senaryo: Elektrik kesintisinden sonra sistem 2 dakikada verileriyle birlikte eski durumuna dönüyor. Hangi alt karakteristik?","b":"<b>Recoverability</b> (Reliability).","t":["senaryo"]},{"id":"6979e42fd7","f":"Senaryo: Tıbbi cihaz yazılımı arıza algılayınca dozu kesip güvenli moda geçiyor. Hangi alt karakteristik?","b":"<b>Fail safe</b> (Safety).","t":["senaryo"]},{"id":"3a0390a228","f":"Senaryo: Hasta kayıtlarını yalnızca yetkili doktorlar görebiliyor. Hangi alt karakteristik?","b":"<b>Confidentiality</b> (Security).","t":["senaryo"]}]},{"id":"d06","no":"6","ad":"Gereksinimler ve Use Case","renk":"#22D3EE","konu":"konu-06-gereksinimler","kartlar":[{"id":"987f8af24b","f":"Gereksinim iş akışının sorduğu temel soru nedir? Yaygın yanılgı?","b":"<b>&quot;What must the product be able to do?&quot;</b><br>Yanılgı: müşterinin ne <i>istediğini</i> belirlemek. Doğrusu: neye <b>ihtiyaç</b> duyduğunu (needs, not wants).","t":["kavram"]},{"id":"27da9febb9","f":"Gereksinim iş akışının adımları?","b":"<ol style='text-align:left'><li>Uygulama alanını (application domain) anla</li><li>İş modelini (business model) kur</li><li>İş modelini kullanarak müşterinin gereksinimlerini belirle</li><li>Adımları <b>yinele</b> (iterate)</li></ol>","t":["liste"]},{"id":"c1878ab83b","f":"<b>Requirements elicitation (capture)</b> ile <b>requirements analysis</b> farkı?","b":"<b>Elicitation:</b> gereksinimleri keşfetme (görüşme, anket).<br><b>Analysis:</b> ilk gereksinimleri inceltme ve genişletme.","t":["tanim","karsilastirma"]},{"id":"a0b11fc1c3","f":"<b>Glossary</b> nedir, neden gerekir?","b":"Alanda kullanılan teknik kelimelerin ve anlamlarının listesi. Müşterinin dilini konuşamazsan gereksinimleri doğru çıkaramazsın.","t":["tanim"]},{"id":"beaf609ee7","f":"<b>Business model</b> nedir?","b":"Bir kurumun <b>iş süreçlerinin</b> tanımı; müşterinin işini bütün olarak anlamayı sağlar.","t":["tanim"]},{"id":"00ce7a35cf","f":"Bilgi toplama teknikleri? Birincil olan hangisi?","b":"<ul style='text-align:left'><li><b>Interviewing</b> (birincil)</li><li>Questionnaire (anket) — yüzlerce kişinin görüşü gerekince</li><li>İş formlarının incelenmesi</li><li>Doğrudan gözlem / video kamera (analizi uzun, mahremiyet sorunu)</li></ul>","t":["liste"]},{"id":"9c3fd90352","f":"Görüşmede iki tür soru? İki tür görüşme?","b":"Sorular: <b>close-ended</b> (belirli cevap) / <b>open-ended</b> (konuşmaya teşvik).<br>Görüşmeler: <b>structured</b> (önceden planlanmış, çoğunlukla kapalı uçlu) / <b>unstructured</b> (cevaplara göre sorulan, çoğunlukla açık uçlu).","t":["karsilastirma","cikmis"]},{"id":"98c14062d4","f":"Görüşmeci nasıl olmalı? Görüşmeden sonra ne yapılır?","b":"Alanı çok iyi tanımalı, her zaman <b>açık fikirli</b> olmalı. Sonra <b>yazılı rapor</b> hazırlanıp bir kopyası görüşülen kişiye verilir.","t":["cikmis"]},{"id":"93ae630e88","f":"<b>Functional</b> ve <b>nonfunctional requirement</b> farkı?","b":"<b>Functional:</b> ürünün yapabilmesi gereken bir <b>eylem</b>; girdi–çıktı ile ifade edilir; requirements/analysis'te ele alınır.<br><b>Nonfunctional:</b> ürünün <b>kendisinin özellikleri</b> (platform, yanıt süresi, güvenilirlik); bazıları <b>design</b>'a kadar bekler.","t":["tanim","karsilastirma","cikmis"]},{"id":"6751badecb","f":"Örnekler fonksiyonel mi? (a) &quot;Öğrenci kitap ödünç alabilmeli&quot; (b) &quot;Arama 2 saniyeden kısa sürmeli&quot; (c) &quot;Aynı anda 200 kullanıcı&quot;","b":"(a) <b>Functional</b><br>(b) <b>Nonfunctional</b> (yanıt süresi)<br>(c) <b>Nonfunctional</b> (kapasite)","t":["senaryo"]},{"id":"b5c1e27a35","f":"<b>Use case</b> nedir?","b":"Yazılım ürününün kendisi ile kullanıcıları (<b>actors</b>) arasındaki bir <b>etkileşimi</b> modeller.<div style='text-align:left'><i>EN:</i> <i>A use case models an interaction between the software product itself and the users of that software product (actors).</i></div>","t":["tanim","cikmis"]},{"id":"e2b63e2f29","f":"<b>Actor</b> nedir?","b":"Yazılım ürününün <b>dışındaki</b> dünyanın bir üyesi; ürüne göre bir <b>rol</b> oynar (kullanıcı, başlatıcı/initiator ya da kritik rol oynayan biri).<div style='text-align:left'><i>EN:</i> <i>An actor is a member of the world outside the software product; it plays a role (user, initiator, or someone who plays a critical part).</i></div>","t":["tanim","cikmis"]},{"id":"424bf2464f","f":"Aktör insan olmak zorunda mı? Örnek?","b":"<b>Hayır.</b> E-ticaret sistemi için <b>kredi kartı şirketinin bilgi sistemi</b> bir aktördür (ve tersi).","t":["kavram"]},{"id":"6d9b888f84","f":"Aktörler bireyler midir? Bir kullanıcı birden fazla rol oynayabilir mi?","b":"Aktörler bireyler değil <b>rollerdir</b>. Bir kişi birden çok rol oynayabilir (banka müşterisi hem <i>Borrower</i> hem <i>Lender</i>); bir aktör birden çok use case'e katılabilir. Yazılımı geliştiren mühendisler aktör değildir.","t":["kavram"]},{"id":"27909fd314","f":"<b>Örtüşen aktörler</b> (overlapping actors) sorunu nasıl çözülür? (hastane örneği)","b":"Bir use case'te <i>Nurse</i>, diğerinde <i>Medical Staff</i> → sorunlu. Çözüm: <i>Medical Staff</i> genel aktörü ve onun özelleşmeleri <i>Physician</i> ve <i>Nurse</i> (<b>generalization</b>, boş üçgen genele doğru).","t":["kavram"]},{"id":"eeac0a0649","f":"Use case diyagramında sistem, aktör, use case ve association nasıl çizilir?","b":"<ul style='text-align:left'><li>Sistem: <b>dikdörtgen</b> (use case'ler içinde)</li><li>Aktör: <b>çöp adam</b>, dikdörtgenin <b>dışında</b></li><li>Use case: <b>elips</b></li><li>Association: aktör ile use case arasında <b>düz çizgi</b></li></ul>","t":["notasyon"]},{"id":"4c8ee0e1df","f":"<b>«include»</b> ne anlama gelir? Okun yönü?","b":"Ortak davranış ana use case'ten dışarı alınmıştır, <b>yeniden kullanım</b> içindir. Ana use case çalışırsa included use case <b>kesinlikle</b> çalışır.<br>Kesikli ok, <b>ana (base) use case → included use case</b>.<div style='color:#888;font-size:0.85em'>💡 Hoca: &quot;Ana olaydan alt adımına doğru olacak, sınavda çıkıyor.&quot;</div>","t":["notasyon","cikmis"]},{"id":"d336bd5438","f":"<b>«extend»</b> ne anlama gelir? Okun yönü?","b":"<b>İstisnai ya da nadir çalışan</b> durumlar (hata, iptal, zaman aşımı). Ana use case çalışsa bile extension çalışmayabilir.<br>Kesikli ok, <b>extension use case → genişletilen (base) use case</b>.","t":["notasyon","cikmis"]},{"id":"7dac54ac3f","f":"include ile extend'in akılda kalıcı farkı (&quot;1 ve 2&quot;)?","b":"<b>include:</b> &quot;1 varsa 2 kesin gerçekleşir.&quot;<br><b>extend:</b> &quot;1 var, 2 olmayabilir de.&quot;","t":["karsilastirma"]},{"id":"475479967d","f":"Use case diyagramında <b>generalization</b> nasıl çizilir?","b":"Düz çizgi + <b>boş üçgen</b>; özel (child) aktör/use case'ten <b>genel (parent)</b> olana doğru. Hoca: &quot;Okun ucu boş, genele doğru.&quot;","t":["notasyon"]},{"id":"8b02fda9dc","f":"<i>Payment</i> ile <i>Approve Card</i> arasında include mı extend mi?","b":"<b>include</b> — kart onayı <b>her ödemede</b> yapılmalıdır. Extend opsiyonel/istisnai durumlar içindir.","t":["senaryo"]},{"id":"8d44267659","f":"<i>Delete Product</i> ile <i>Cancel</i>/<i>Timeout</i> arasında hangi ilişki, ok yönü?","b":"<b>«extend»</b>; ok <b>Cancel → Delete Product</b> ve <b>Timeout → Delete Product</b> (istisna → ana).","t":["senaryo","cikmis"]},{"id":"75ac8ede44","f":"Adres defterinde <i>Sil</i> ile <i>Detayları Gör</i>, <i>Detayları Gör</i> ile <i>Ara</i> arasındaki ilişki?","b":"<b>«include»</b>: silmek için önce detaylar görülür, detay için önce arama yapılır — her seferinde. Ok: Sil → Detayları Gör → Ara.","t":["senaryo","cikmis"]},{"id":"586571d96d","f":"PurchaseTicket örneğinde «extend» ve «include» use case'leri?","b":"«extend» → <i>OutOfOrder, TimeOut, Cancel, NoChange</i> PurchaseTicket'ı genişletir.<br>«include» → <i>PurchaseSingleTicket</i> ve <i>PurchaseMultiCard</i> ortak <i>CollectMoney</i>'yi kullanır.","t":["ornek"]},{"id":"3179e10a3b","f":"Bir use case'in mutlaka sağlaması gereken koşul nedir? (MSG'den ders)","b":"Bir <b>aktörle etkileşmek zorundadır</b>. Aktörle etkileşmeyen davranış (ör. <i>Estimate Payments and Grants for Week</i>) kendi başına use case olamaz, bir use case'in parçasıdır (include).","t":["kavram"]},{"id":"55cea638f6","f":"«include»'un olağan nedeni nedir?","b":"Bir use case'in <b>iki veya daha fazla</b> use case'in parçası olması (aynı davranışı birden çok yere yazmamak).","t":["kavram"]},{"id":"6cc455703e","f":"Use case diyagramı ile use case açıklamaları arasındaki ilişki?","b":"Diyagram sadece bir <b>indekstir</b>; modelin asıl &quot;eti&quot; <b>use case açıklamalarıdır</b>. Bütün use case'ler açıklanmalıdır.","t":["kavram"]},{"id":"2547e14a38","f":"Use case açıklama şablonunun <b>alanları</b>? (hocanın şablonu)","b":"<ol style='text-align:left'><li>Use case name (unique)</li><li>Brief description</li><li>Participating actors</li><li>Entry condition (pre-condition)</li><li>Exit condition (post-condition)</li><li>Flow of events / step-by-step description</li><li>Exceptional / special cases</li></ol><div style='color:#888;font-size:0.85em'>💡 WhatsApp: &quot;brief description da istiyormuş&quot;.</div>","t":["liste","cikmis","hoca_sorar","ezber"]},{"id":"9d8a8fe509","f":"<b>Pre-condition</b> ile <b>post-condition</b> farkı?","b":"<b>Pre (entry):</b> use case başlamadan önce doğru olması gerekenler.<br><b>Post (exit):</b> use case bitince doğru olanlar.","t":["tanim"]},{"id":"6b871bc24c","f":"Purchase ticket örnek açıklamasında eksik olan alan neydi?","b":"<b>Exceptional cases!</b> (Name, actor, entry, exit, event flow vardı.)","t":["ornek"]},{"id":"45bedf56dc","f":"<b>Kişi Ekle</b> (adres defteri) use case açıklamasını yaz.","b":"<ul style='text-align:left'><li><b>Brief:</b> Kullanıcıdan alınan kişi bilgilerinin sisteme kaydedilmesi.</li><li><b>Actor:</b> User</li><li><b>Pre:</b> Eklenecek kişinin isim ve soyisim bilgileri bilinmelidir.</li><li><b>Post:</b> Kişi sisteme eklenir.</li><li><b>Steps:</b> 1. İsim-soyisim alınır, varsa adres ve telefon alınır. 2. Sisteme kaydedilir.</li><li><b>Special:</b> Kişi zaten var; kullanıcı vazgeçti; hafıza dolu.</li></ul>","t":["cikmis","senaryo_cozum"]},{"id":"6c2284f1a5","f":"<b>Kişi Güncelle</b> (adres defteri) use case açıklamasını yaz.","b":"<ul style='text-align:left'><li><b>Brief:</b> Bulunan bir kişinin telefon ve adres bilgisinin güncellenmesi.</li><li><b>Entry:</b> Kişinin isim ve soyismi belirtilir.</li><li><b>Exit:</b> Adres ve telefon güncellenir.</li><li><b>Steps:</b> 1. İsim-soyisim girilir. 2. Kişi aranır. 3. Varsa yeni adres/telefon girilir. 4. Sistem günceller.</li><li><b>Exceptional:</b> Kişi yok; kullanıcı vazgeçti.</li></ul>","t":["cikmis","senaryo_cozum"]},{"id":"1853364522","f":"Adres defteri senaryosunun use case'leri ve extend'leri?","b":"Aktör: User. Use case'ler: <b>Kişi Ekle, Listele, Ara, Detayları Gör, Sil, Güncelle</b>.<br>extend: Hafıza dolu, Kişi zaten var → Ekle; Liste boş → Listele; Kişi yok → Ara; Vazgeç → Ekle/Sil/Güncelle.<br>include: Detayları Gör → Ara; Sil, Güncelle → Detayları Gör.","t":["cikmis","senaryo_cozum"]},{"id":"d66e49b10e","f":"2024–25 e-ticaret vizesi: aktörler ve use case'ler?","b":"<b>User:</b> Login, Register, List Products («include» Search/Filter), View Cart, Payment («include» Approve Card).<br><b>Admin:</b> Modify Users, Add Product, Update Product, Delete Product («include» Search/Filter); Cancel, Timeout «extend» Delete Product.","t":["cikmis","senaryo_cozum"]},{"id":"8f49c5bfc7","f":"<b>Delete Product</b> use case açıklaması (hocanın çözümü)?","b":"<ul style='text-align:left'><li><b>Brief:</b> Admin product deletion process is described.</li><li><b>Actor:</b> Admin</li><li><b>Pre:</b> The product is found.</li><li><b>Post:</b> The product is deleted.</li><li><b>Steps:</b> 1. Admin searches the product. 2. Product details are shown. 3. Admin approves the deletion. 4. The product is deleted <b>in 5 ms</b>.</li><li><b>Special:</b> Time out; Cancel.</li></ul><div style='color:#888;font-size:0.85em'>💡 Hoca kısıtı adımlara somut yazmayı seviyor (&quot;in 5 ms&quot;).</div>","t":["cikmis","senaryo_cozum"]},{"id":"e2703202a7","f":"<b>Payment</b> use case açıklaması (e-ticaret)?","b":"<ul style='text-align:left'><li><b>Brief:</b> The user pays for the products in the cart.</li><li><b>Actors:</b> User (+ bank system, non-human)</li><li><b>Pre:</b> logged in, cart not empty, products in stock.</li><li><b>Post:</b> payment completed, order created, stock decreased.</li><li><b>Steps:</b> 1. view cart, select payment 2. enter card 3. system approves card (include) 4. order created, confirmation.</li><li><b>Special:</b> card not approved; out of stock; user cancels.</li></ul>","t":["cikmis","senaryo_cozum"]},{"id":"0a9dd8ab51","f":"Use case diyagramı çizerken puan kaybettiren 4 hata?","b":"<ol style='text-align:left'><li>Aktörü sistem dikdörtgeninin <b>içine</b> çizmek</li><li>Aktör–use case arasına ok/kesikli çizgi çizmek (düz çizgi olmalı)</li><li>include/extend okunun üstüne stereotip yazmamak</li><li>Ok yönlerini ters çizmek (include: ana→alt; extend: istisna→ana)</li></ol>","t":["sinav_taktigi"]},{"id":"9271e4efe0","f":"2014 vizesi: &quot;Proje yöneticisi, takım lideri, yazılımcılar&quot; — use case'ler için aktörleri nasıl modellersin?","b":"Üç aktör: <b>Proje Yöneticisi, Takım Lideri, Yazılımcı</b>; istenirse ortak <b>Çalışan</b> aktörü ve üçü ondan <b>generalization</b> (boş üçgen genele).","t":["cikmis"]},{"id":"783a89653a","f":"MSG Foundation nedir, pilot projede ne isteniyor?","b":"Genç çiftlere <b>düşük maliyetli ipotek (mortgage)</b> veren vakıf. Pilot proje: her hafta ev almak için ne kadar para olduğunu belirleyen yazılım.","t":["vaka"]},{"id":"1837f1b57b","f":"MSG'de başvuranlar (Applicants) yazılımla doğrudan etkileşmiyor. Neden yine de aktördür?","b":"Use case'i <b>başlatan</b> ve veriyi <b>sağlayan</b> onlardır; MSG personeli sadece aracıdır. Aynı mantıkla Borrowers da aktördür.","t":["vaka"]},{"id":"163f92fb9f","f":"MSG haftalık kullanılabilir fon formülü?","b":"(1) yıllık yatırım geliri/52 − (2) yıllık işletme gideri/52 + (3) haftalık ipotek ödemeleri − (4) haftalık hibeler = (5) haftalık fon. Ev fiyatı (5)'ten büyük değilse fon verilir; harcanmayan para yatırıma gider.","t":["vaka"]},{"id":"1b3ba5bb34","f":"MSG use case revizyonunda <i>Update Borrowers' Weekly Income</i> neden silindi? Buna ne denir?","b":"Haftalık gelir ipoteğin bir özelliği; <i>Manage a Mortgage</i> zaten bunu yapıyor. Bu bir <b>decrement</b>'tir (iterate and increment bazen decrement demektir).","t":["vaka"]},{"id":"ef91081660","f":"MSG'de test workflow ile bulunan unutulmuş use case'ler?","b":"<i>Manage a Mortgage</i> ve <i>Produce a Report</i>.","t":["vaka"]},{"id":"3d64fd7db2","f":"<b>Rapid prototyping</b> ile OO yaklaşımın (use case) farkı?","b":"Prototip hızlı yapılıp <b>atılır</b>; use case ve senaryolar her yinelemede <b>inceltilir</b>. Yine de UI prototipi (örnek ekran/rapor) gerekir.","t":["karsilastirma"]},{"id":"40fbe2de14","f":"<b>CASE</b> aracı nedir? Örnekler?","b":"Computer-Aided Software Engineering: UML diyagramlarını çizmek/değiştirmek, belge saklamak için araçlar. IBM Rational Rose, Together, ArgoUML, System Architect.","t":["tanim","cikmis"]},{"id":"faeb0f6644","f":"Gereksinim iş akışı metrikleri: <b>volatility</b> ve <b>speed of convergence</b>?","b":"Gereksinimlerin ne kadar değiştiği ve müşteri ihtiyaçlarının ne hızla belirlendiği. Sonraki fazlarda değişiklik geliştiriciden geliyorsa süreç kusurlu; müşteriden geliyorsa moving target.","t":["tanim"]}]},{"id":"d07","no":"7","ad":"Nesne Yönelimli Analiz","renk":"#FB923C","konu":"konu-07-oo-analiz","kartlar":[{"id":"aa993ec3d9","f":"<b>Object-oriented analysis (OOA)</b> nedir? Analiz iş akışının iki amacı?","b":"OO paradigmanın <b>yarı biçimsel (semiformal)</b> analiz tekniği; bu iş akışında <b>sınıflar çıkarılır</b>.<br>Amaçlar: gereksinimleri <b>daha derin anlamak</b> ve onları <b>bakımı kolay</b> bir tasarım ve gerçekleştirmeye götürecek şekilde tanımlamak.","t":["tanim"]},{"id":"c3edea8ff0","f":"Analiz iş akışındaki <b>üç sınıf türü</b>?","b":"<ol style='text-align:left'><li><b>Entity class</b></li><li><b>Boundary class</b></li><li><b>Control class</b></li></ol>Üçü de UML'in <b>stereotype</b> genişletmesidir.","t":["liste","cikmis"]},{"id":"d1be973adf","f":"<b>Entity class</b> neyi modeller? Örnek?","b":"<b>Uzun ömürlü (long-lived) bilgiyi</b>; gerçek sistemdeki varlıkları.<br>Örnek: Account, Investment, Mortgage, Kişi, Araç.<div style='text-align:left'><i>EN:</i> <i>An entity class models information that is long lived.</i></div>","t":["tanim","cikmis"]},{"id":"ff13c3703e","f":"<b>Boundary class</b> neyi modeller? Örnek?","b":"Ürün ile <b>çevresi (aktörler) arasındaki etkileşimi</b>; genellikle <b>giriş/çıkış</b>. Her giriş ekranı, çıkış ekranı ve basılı rapor bir boundary sınıfıdır.<br>Örnek: User Interface Class, Investments Report Class.<div style='text-align:left'><i>EN:</i> <i>A boundary class models the interaction between the product and the environment; it is generally associated with input or output.</i></div>","t":["tanim","cikmis"]},{"id":"a4e09d91d8","f":"<b>Control class</b> neyi modeller? Örnek?","b":"<b>Karmaşık hesaplamaları ve algoritmaları</b>; use case akışını yönetir. Her önemsiz olmayan hesaplama bir control sınıfıdır.<br>Örnek: Estimate Funds for Week Class, Elevator Controller.<div style='text-align:left'><i>EN:</i> <i>A control class models complex computations and algorithms.</i></div>","t":["tanim","cikmis"]},{"id":"329cdbd93e","f":"Entity / boundary / control sınıflarının simgeleri (hocanın tahtası)?","b":"Entity: <b>altı çizili daire</b>.<br>Boundary: <b>solunda dikey çizgi olan daire</b>.<br>Control: <b>üstünde ok olan daire</b>.<br>Stereotipler: «entity», «boundary», «control».","t":["notasyon"]},{"id":"06f56bca33","f":"Sınıf türünü söyle: (a) KiralamaEkrani (b) Musteri (c) UcretHesaplayici (d) FaturaRaporu","b":"(a) <b>Boundary</b> (b) <b>Entity</b> (c) <b>Control</b> (d) <b>Boundary</b> (rapor = çıktı)","t":["senaryo"]},{"id":"22649000ad","f":"Entity sınıflarını çıkarmanın <b>üç adımı</b>?","b":"<ol style='text-align:left'><li><b>Functional modeling:</b> bütün use case'lerin senaryolarını sun</li><li><b>Entity class modeling:</b> entity sınıfları, nitelikleri, ilişkileri → <b>class diagram</b></li><li><b>Dynamic modeling:</b> her sınıfa/sınıfın yaptığı işlemler → <b>statechart</b></li></ol>Bu adımlar artırımlı ve yinelemeli yapılır.","t":["liste","cikmis"]},{"id":"85b3f5b6c2","f":"<b>Scenario</b> nedir?","b":"Bir use case'in <b>bir örneği</b> (instance). Hedef ürünü kavramak için <b>yeterli sayıda</b> senaryo incelenir (ne çok fazla ne çok az).<div style='text-align:left'><i>EN:</i> <i>A scenario is an instance of a use case.</i></div>","t":["tanim"]},{"id":"5e026e8a42","f":"Normal ve exceptional senaryo farkı? (asansör örneği)","b":"<b>Normal:</b> beklenen akış (User A 3. katta yukarı düğmesine basar, 7. kata gider…).<br><b>Exceptional:</b> beklenmeyen durum (yukarıya bastı ama aşağı gitmek istediğini fark etti, yanlış asansöre bindi).","t":["kavram"]},{"id":"f5c1c12ca9","f":"Asansör probleminin iki use case'i?","b":"<b>Press an Elevator Button</b> ve <b>Press a Floor Button</b> (aktör: User).","t":["vaka"]},{"id":"11690d7420","f":"<b>Noun extraction</b> nasıl yapılır? (2 aşama)","b":"<ol style='text-align:left'><li>Ürünü <b>tek paragrafta</b> tanımla (kısa problem tanımı)</li><li><b>İsimleri</b> belirle; problem sınırının <b>dışındakileri</b> ve <b>soyut isimleri</b> ele; kalanlar aday sınıflar</li></ol><div style='color:#888;font-size:0.85em'>💡 Soyut isimler sınıf değil ama nitelik olabilir.</div>","t":["tanim","cikmis"]},{"id":"8206a4673f","f":"Asansör paragrafındaki isimler hangileri? Hangileri neden elendi?","b":"İsimler: button, elevator, floor, movement, building, illumination, request, door.<br><b>floor, building, door</b> → problem sınırının dışında. <b>movement, illumination, request</b> → soyut isimler.<br>Kalan: <b>Elevator</b> ve <b>Button</b> (alt sınıflar: Elevator Button, Floor Button).","t":["vaka"]},{"id":"681d0d0070","f":"Asansörde neden <b>Elevator Controller Class</b> eklendi?","b":"Düğmeler asansörlerle doğrudan iletişim kurmaz; bir kontrolcü gerekir. Böylece bütün ilişkiler <b>1-to-n</b> olur, tasarım ve gerçekleştirme kolaylaşır.","t":["vaka"]},{"id":"49684b1e73","f":"Asansör sınıf diyagramındaki çokluklar (m kat, n asansör)?","b":"Elevator Button (<b>m·n</b>) — 1 Elevator Controller<br>Floor Button (<b>2m−2</b>) — 1 Elevator Controller<br>Elevator Controller 1 — <b>n</b> Elevator","t":["vaka"]},{"id":"49e75bdc05","f":"<b>CRC kartı</b> nedir? Alanları?","b":"<b>Class–Responsibility–Collaboration</b> kartı (1989'dan beri).<br><ul style='text-align:left'><li><b>Class:</b> sınıfın adı</li><li><b>Responsibility:</b> sınıfın işlevleri (ne yapar, neyi bilir)</li><li><b>Collaboration:</b> çağırdığı / birlikte çalıştığı sınıflar</li></ul>","t":["tanim","cikmis"]},{"id":"c88be90f2f","f":"CRC kartlarının güçlü ve zayıf yanı?","b":"<b>Güçlü:</b> ekip kartları canlandırınca (act out) <b>eksik veya hatalı öğeleri</b> ortaya çıkarır → iyi bir <b>test</b> tekniği.<br><b>Zayıf:</b> entity sınıflarını bulmak için kullanılırsa <b>alan uzmanlığı</b> gerekir.","t":["cikmis"]},{"id":"9f2ca88c34","f":"Elevator Controller CRC kartındaki &quot;1. Turn on elevator button&quot; sorumluluğunun hatası? Doğrusu?","b":"<b>Responsibility-driven design</b> ve <b>information hiding</b> ihlali — kontrolcü düğmenin işini kendisi yapıyor.<br>Doğrusu: <i>&quot;Send message to Elevator Button Class to turn itself on.&quot;</i>","t":["vaka"]},{"id":"5ffad212b8","f":"CRC ile asansörde hangi unutulmuş sınıf bulundu?","b":"<b>Elevator Doors Class</b> — kapıların çalışma sırasında değişen bir durumu var (güvenlik açısından da önemli).","t":["vaka"]},{"id":"ba862a0cd6","f":"<b>God class</b> nedir? Çözümü?","b":"<b>Çok fazla bilgiye maruz kalan ve çok fazla kontrole sahip</b> sınıf; bilinen bir <b>antipattern</b>.<br>Çözüm: <b>kontrolü dağıtmak</b> (distributed decentralized architecture).<div style='text-align:left'><i>EN:</i> <i>A god class is exposed to too much information and has too much control.</i></div>","t":["tanim","cikmis"]},{"id":"314c9cfdc7","f":"Asansörde kontrol nasıl dağıtıldı (distribute the control)?","b":"Her asansöre bir <b>Elevator Subcontroller</b>, her kata bir <b>Floor Subcontroller</b>; m+n alt kontrolcü istekleri işleyen bir <b>Scheduler</b> ile konuşur; katlardaki <b>Sensor</b>'lar asansör yaklaşınca/uzaklaşınca alt kontrolcüyü bilgilendirir.","t":["vaka","cikmis"]},{"id":"255751943a","f":"Statechart notasyonu: başlangıç, bitiş, durum, geçiş?","b":"Başlangıç: <b>dolu siyah daire</b>.<br>Bitiş: <b>içinde küçük siyah daire olan daire</b>.<br>Durum: <b>köşeleri yuvarlatılmış dikdörtgen</b>.<br>Geçiş: <b>ok</b> (üzerinde tetikleyen olay).","t":["notasyon"]},{"id":"d89a712298","f":"MSG dinamik modelinde (statechart) bir menü seçimi neye karşılık gelir?","b":"Bir <b>olaya (event)</b>; durum geçişine yol açar. İşlem bitince sistem <i>MSG Foundation Information System Loop</i> durumuna döner; &quot;quit&quot; bitişe götürür.","t":["vaka"]},{"id":"544a5a40d8","f":"MSG noun extraction sonucu aday entity sınıfları? Neden ortak üst sınıf eklendi?","b":"<b>Mortgage Class</b> ve <b>Investment Class</b> (report/list uzun ömürlü değil, money soyut).<br>İkisine yapılan işlemler çok benzer (ekle, sil, değiştir, yazdır) → üst sınıf <b>Asset Class</b>; use case'ler <i>Manage an Asset</i>'te birleşti.","t":["vaka"]},{"id":"2d1da9cb48","f":"MSG'de neden <b>MSG Application Class</b> eklendi?","b":"Yıllık işletme giderlerinin (ve haftalık hesap sonucunun) saklanacağı bir sınıf yoktu.","t":["vaka"]},{"id":"ea6b42a54e","f":"MSG'nin boundary ve control sınıfları?","b":"Boundary: <b>User Interface Class</b> (tek ekran) + üç rapor: <b>Estimated Funds Report, Mortgages Report, Investments Report</b>.<br>Control: tek hesaplama → <b>Estimate Funds for Week Class</b>.","t":["vaka"]},{"id":"1d27c984a9","f":"<b>Use-case realization</b> nedir?","b":"Use case'leri <b>genişletip inceltme</b> süreci. Bir senaryonun gerçekleştirilmesi bir <b>interaction diagram</b> (sequence ya da collaboration) ile gösterilir.","t":["tanim"]},{"id":"8986325ec3","f":"Interaction diagram'ın iki türü?","b":"<b>Sequence diagram</b> ve <b>collaboration (communication) diagram</b> — tamamen eşdeğerdir, birbirine dönüştürülebilir.","t":["tanim"]},{"id":"674d30dd08","f":"Use-case realization artifact zinciri (7 öğe)?","b":"<ol style='text-align:left'><li>Use case (diyagram)</li><li>Use case açıklaması</li><li>Class diagram</li><li>Scenario</li><li>Collaboration diagram</li><li>Flow of events (collaboration'ın yazılı anlatımı)</li><li>Sequence diagram</li></ol>","t":["liste"]},{"id":"f3faff025c","f":"Çalışan bir sistem sınıfları mı nesneleri mi kullanır? Diyagramda nasıl gösterilir?","b":"<b>Nesneleri.</b> Belirli bir ipotek <code>: Mortgage Class</code> şeklinde gösterilir.","t":["notasyon"]},{"id":"57e513db20","f":"<b>Collaboration diagram</b> nedir?","b":"Nesneleri, aralarındaki <b>bağlantıları (links)</b> ve bağlantılar üzerinde <b>gönderilme sırasına göre numaralanmış</b> mesajları gösterir. Dikey zaman ekseni yoktur.<div style='text-align:left'><i>EN:</i> <i>A collaboration diagram shows the objects, the links between them and the messages numbered in the order in which they are sent.</i></div>","t":["tanim","cikmis"]},{"id":"c5c6b467c3","f":"<b>Sequence diagram</b> nedir?","b":"Nesneleri ve aralarındaki mesajları <b>zaman sırasıyla</b> (yukarıdan aşağıya) gösterir; çağrılar düz, dönüşler kesikli oktur.","t":["tanim"]},{"id":"865f29a062","f":"Sequence mı collaboration mı? Hangisi ne zaman daha iyi?","b":"<b>Sequence:</b> mesajların akışı ve <b>sırası</b> açık; odak bilgi aktarımı ise üstün.<br><b>Collaboration:</b> sınıf diyagramına benzer; geliştiriciler <b>sınıflara</b> odaklanıyorsa kullanışlı.","t":["karsilastirma"]},{"id":"f8bca20207","f":"Analiz aşamasındaki sequence oklarına ne yazılır, sınavda ne yazmalısın?","b":"Analizde metotlar belli olmadığından açıklama (&quot;Request estimated return…&quot;). Tasarımda/sınavda <b>metot adları</b>: her ok <b>okun ucundaki sınıfın metodu</b> olmalı (parametreli).","t":["sinav_taktigi","cikmis"]},{"id":"7ffdc0c115","f":"Estimate Funds for Week senaryosuna giren 6 sınıf ve türleri?","b":"User Interface (<b>boundary</b>), Estimate Funds for Week (<b>control</b>), Investment, Mortgage, MSG Application (<b>entity</b>), Estimated Funds Report (<b>boundary</b>).","t":["vaka"]},{"id":"d69465215d","f":"Estimate Funds collaboration'ında 9 numaralı mesaj nedir? Özelliği?","b":"&quot;Compute estimated amount available for week&quot; — Estimate Funds for Week nesnesinin <b>kendine</b> gönderdiği mesaj (<b>self call</b>).","t":["vaka"]},{"id":"829e27fff7","f":"Adres defteri: sınıflar ve türleri (hocanın kâğıdı)?","b":"<b>Kisi</b> → entity (uzun ömürlü bilgi)<br><b>Menu</b> → boundary (menü, bilgi alma)<br><b>AdresDefteri</b> → control (ekle, ara, sırala, düzenle)<br><b>Program</b> diğerlerini kullanır («uses» = dependency).","t":["cikmis","senaryo_cozum"]},{"id":"aea6f29680","f":"Adres defteri: AdresDefteri ile Kisi arasındaki ilişki? Aggregation mı composition mı?","b":"Hocanın kâğıdında <b>aggregation</b> (AdresDefteri ◇— Kisi, 1–n, elmas AdresDefteri tarafında). Tahtadaki yeni sürümde <b>composition</b>.<br>İkisi de geçerli; <b>gerekçeyle</b> yaz: kişiler defterle silinir → composition; bağımsız yaşar → aggregation.","t":["cikmis","senaryo_cozum"]},{"id":"0cec3368d9","f":"Adres defteri CRC: <b>AdresDefteri</b> kartı?","b":"<b>Responsibility:</b> kişi ekler, siler, düzenler; arama ve sıralama yapar.<br><b>Collaboration:</b> Kisi, Program.","t":["senaryo_cozum"]},{"id":"3c62e69d8b","f":"Adres defteri CRC: <b>Menu</b> kartı?","b":"<b>Responsibility:</b> ana menüyü gösterir; kişi ekleme bilgilerini alır; arama bilgisini alır.<br><b>Collaboration:</b> Kisi, AdresDefteri, Program.","t":["senaryo_cozum"]},{"id":"cf0763c302","f":"Kişi Ekle sequence diyagramının mesaj sırası?","b":"<ol style='text-align:left'><li>Kullanıcı → Menu: <code>eklemeIstegi()</code></li><li>Menu → Menu: <code>KisiBilgileriniAl()</code> (self)</li><li>Menu → Kisi: «create» <code>Kisi(ad, soyad, tel, adres)</code></li><li>Menu → AdresDefteri: <code>Ekle(kisi)</code></li><li>AdresDefteri → AdresDefteri: <code>kaydet()</code> (boyut kontrolü)</li><li>AdresDefteri ⇢ Menu: işlem tamam</li><li>Menu ⇢ Kullanıcı: işlem tamam</li></ol>","t":["senaryo_cozum"]},{"id":"81e8a0058c","f":"2014 vizesi senaryo sorusunun dört alt sorusu (proje takip sistemi, 40 p)?","b":"<ol style='text-align:left'><li>Use case'leri oluştur</li><li>Class yapısını oluştur, türlerini (entity/boundary/control) belirt</li><li>Class'ların tasarımını oluştur</li><li>Collaboration veya sequence diyagramı</li></ol>","t":["cikmis"]},{"id":"ffe13f66cc","f":"Proje takip sisteminde sınıf türleri?","b":"Entity: Proje, Gorev, Calisan (ProjeYoneticisi, TakimLideri, Yazilimci).<br>Boundary: ProjeEkrani, GorevEkrani, IlerlemeRaporu.<br>Control: GorevAtamaKontrol, IlerlemeHesaplayici.","t":["cikmis","senaryo_cozum"]},{"id":"2d247c9d1a","f":"Unified Process neden &quot;use-case driven&quot;dır? Spesifikasyon belgesinin yerini ne alır?","b":"Use case'ler ve onlardan türeyen artifact'lar geleneksel metin spesifikasyonunun yerini alır ve aynı <b>sözleşme</b> rolünü oynar.","t":["kavram"]},{"id":"d93ddc533d","f":"UP'de aktör (rol) için kullanılan terim nedir?","b":"<b>Worker</b> (ör. Applicants ve Borrowers iki ayrı worker).","t":["tanim"]},{"id":"41ca1f288c","f":"OOA'nın zorlukları?","b":"OO tasarımın sınırını geçme (analizde tasarım yapma); sınıflara <b>henüz metot atama</b> (stepwise refinement sırasında yeniden dağıtmak boşa emek).","t":["kavram"]},{"id":"32ac734d8b","f":"OOA'da boyut (size) metriği nedir?","b":"<b>UML diyagramlarının sayfa sayısı</b>.","t":["tanim"]}]},{"id":"d08","no":"8","ad":"UML Diyagramları","renk":"#818CF8","konu":"konu-08-uml","kartlar":[{"id":"75cd24f66b","f":"<b>UML</b> nedir? Bir süreç midir?","b":"<b>Unified Modeling Language</b>: OMG standardı grafik modelleme dili; yazılımı <b>belirlemek, görselleştirmek, inşa etmek ve belgelemek</b> için. Booch, Rumbaugh, Jacobson'a dayanır. <b>Bir süreç değildir</b> ve <b>programlama dilinden bağımsızdır</b>.","t":["tanim"]},{"id":"4480894752","f":"UML'de <b>model</b>, <b>view</b>, <b>notation</b> nedir?","b":"<b>Model:</b> sistemin bir alt kümesini tanımlayan soyutlama.<br><b>View:</b> modelin seçilmiş yönlerini gösterir.<br><b>Notation:</b> görünümleri çizmek için grafik/metin kuralları.","t":["tanim"]},{"id":"797ef8e13c","f":"UML'in &quot;80/20&quot; kuralı?","b":"Problemlerin <b>%80'i UML'in %20'siyle</b> modellenebilir.","t":["kavram"]},{"id":"90a816c985","f":"Statik ve dinamik UML diyagramları hangileri?","b":"<b>Statik</b> (yapı, değişmez): class, object, package, component, deployment.<br><b>Dinamik</b> (davranış, senaryoya göre değişir): sequence, collaboration, activity, state.","t":["karsilastirma"]},{"id":"4727502cba","f":"Class diyagramı statik midir? Neyi gösterir, neyi göstermez?","b":"Statiktir: <b>neyin neyle etkileştiğini</b> gösterir ama etkileşince <b>ne olduğunu</b> göstermez. Sınıfların nitelik ve işlemlerini gösterir.","t":["kavram"]},{"id":"90e77a5ce0","f":"Class diyagramının üç bakış açısı?","b":"<ol style='text-align:left'><li><b>Conceptual</b> (yazılımdan ve dilden bağımsız)</li><li><b>Specification</b> (arayüzlere odaklı)</li><li><b>Implementation</b> (gerçekleştirmeye odaklı)</li></ol>","t":["liste"]},{"id":"45e3a674c7","f":"Sınıf kutusunun üç bölmesi? Zorunlu olan?","b":"<ol style='text-align:left'><li>Sınıf adı (<b>tek zorunlu</b>)</li><li>Nitelikler (attributes) ve tipleri</li><li>İşlemler (operations) ve imzaları</li></ol>","t":["notasyon"]},{"id":"0b1b765227","f":"Görünürlük işaretleri: <code>-</code>, <code>+</code>, <code>#</code>, altı çizili?","b":"<code>-</code> private, <code>+</code> public, <code>#</code> protected, <u>altı çizili</u> = <b>static</b>.","t":["notasyon"]},{"id":"f3625b1c05","f":"Sınıf adı <i>italik</i> yazılmışsa ne anlama gelir?","b":"<b>Abstract class</b> — doğrudan nesne üretilmez; gövdesiz üyeler alt sınıflarda tamamlanır.","t":["notasyon"]},{"id":"4bdfc951e5","f":"Instance (nesne) gösterimi?","b":"Adı <b>altı çizili</b>, sınıfını içerebilir: <u>tarif_1974 : TariffSchedule</u>; nitelikler değerleriyle yazılır.","t":["notasyon"]},{"id":"5759ca550b","f":"Sınıflar arası ilişki türlerini say (6+).","b":"<ul style='text-align:left'><li>Association (binary / unary-directed / reflexive)</li><li>Aggregation</li><li>Composition</li><li>Inheritance (generalization)</li><li>Realization</li><li>Dependency</li></ul>","t":["liste","cikmis"]},{"id":"35267618c1","f":"<b>Binary association</b>: anlamı ve çizimi?","b":"İki sınıf <b>birbirinden haberdar</b>, birbirinin metotlarını çağırabilir. <b>Düz çizgi</b> (ok yok).<br>Örnek: Customer — Order.","t":["iliski","cikmis"]},{"id":"05cef21743","f":"<b>Unary (directed) association</b>: anlamı ve çizimi? Ok kime bakar?","b":"Tek yönlü: A, B'nin metodunu çağırır; B'nin A'dan haberi yok. <b>Açık uçlu ok, çağrılan sınıfa (B) doğru</b>.<br>Örnek: OrderDetail → Item.","t":["iliski","cikmis"]},{"id":"1b090747aa","f":"<b>Reflexive association</b> nedir?","b":"Bir sınıfın <b>kendisiyle</b> ilişkisi (sınıfın birden çok rolü varsa). Örnek: Employee (yönetici) — Employee (çalışan).","t":["iliski"]},{"id":"10f3ab7cd4","f":"<b>Aggregation</b>: anlamı, çizimi, örnek?","b":"&quot;Topluluk–üye&quot; (zayıf has-a): bir sınıf diğerinin nesnelerinden oluşan bir topluluğu içerir; <b>tek sahiplik yok</b>, parça bütün olmadan yaşayabilir.<br><b>Boş elmas, bütün (topluluk) tarafında</b>.<br>Örnek: Takım ◇— Oyuncu.","t":["iliski","cikmis"]},{"id":"b38b1d55ee","f":"<b>Composition</b>: anlamı, çizimi, örnek?","b":"Aggregation'ın güçlü hâli: <b>bütün, parçaların oluşturulmasından ve silinmesinden sorumludur</b> (lifetime control); parça tek bütüne aittir, bütün olmadan var olamaz.<br><b>Dolu elmas, bütün tarafında</b>.<br>Örnek: Ev ◆— Oda.","t":["iliski","cikmis"]},{"id":"0c87763b4d","f":"Aggregation ile composition arasındaki <b>kritik fark</b>?","b":"<b>Yaşam döngüsü kontrolü.</b> Composition'da parça bütünle birlikte yaratılır/yok edilir ve bütünsüz var olamaz; aggregation'da parça bağımsız yaşar.","t":["karsilastirma","cikmis"]},{"id":"582500ff35","f":"<b>Inheritance (generalization)</b>: anlamı ve çizimi?","b":"&quot;<b>is-a</b>&quot;: alt sınıf üst sınıfın nitelik ve işlemlerini miras alır. Düz çizgi + <b>boş üçgen, ata (üst) sınıfa doğru</b>.<br>Örnek: Gül → Çiçek; Credit, Cash, Check → Payment.","t":["iliski","cikmis"]},{"id":"1f0548f393","f":"<b>Realization</b>: anlamı ve çizimi?","b":"Bir sınıfın bir <b>arayüzü (interface)</b> gerçekleştirmesi (&quot;<b>can-do</b>&quot;). <b>Kesikli çizgi + boş üçgen, arayüze doğru</b>.<br>Örnek: Kuş - - ▷ «interface» Uçabilir.","t":["iliski","cikmis"]},{"id":"bb0f870429","f":"<b>Dependency</b>: anlamı ve çizimi?","b":"&quot;<b>uses-a</b>&quot;: bir sınıf diğerini <b>geçici</b> kullanır (parametre, yerel değişken); diğerindeki değişiklik onu etkileyebilir. <b>Kesikli çizgi + açık uçlu ok</b>.<br>Örnek: Librarian - - «use» > Search.","t":["iliski","cikmis"]},{"id":"983ebb42ac","f":"Realization ile inheritance çizimindeki fark?","b":"İkisinde de <b>boş üçgen</b>. Inheritance <b>düz</b> çizgi (üst sınıfa), realization <b>kesikli</b> çizgi (arayüze).","t":["karsilastirma","notasyon"]},{"id":"a84c70e8e7","f":"Dependency ile directed association çizimindeki fark?","b":"İkisinde de açık uçlu ok. Directed association <b>düz</b> çizgi (kalıcı bağ, alan), dependency <b>kesikli</b> çizgi (geçici kullanım).","t":["karsilastirma","notasyon"]},{"id":"ae9cfaa5b0","f":"Elmas hangi tarafa çizilir? Üçgen? Directed association oku?","b":"Elmas: <b>bütünün (collection/whole)</b> yanına, bitişik.<br>Kalıtım/realization üçgeni: <b>ata sınıfa / arayüze</b>.<br>Directed association oku: <b>çağrılan</b> sınıfa.<div style='color:#888;font-size:0.85em'>💡 Hoca: &quot;Bazı arkadaşlarımız elması ortaya ya da ters tarafa çiziyor. Bunlar yanlış.&quot;</div>","t":["notasyon","sinav_taktigi"]},{"id":"d84e8eb661","f":"C# kodu hangi ilişki?<pre style='text-align:left;font-size:0.85em'>class Takim { List&lt;Oyuncu&gt; oyuncular;<br>              public void Ekle(Oyuncu o) { oyuncular.Add(o); } }</pre>","b":"<b>Aggregation</b> — oyuncu dışarıda yaratılıp eklenir, takımdan bağımsız yaşar.","t":["kod","iliski"]},{"id":"139451de6b","f":"C# kodu hangi ilişki?<pre style='text-align:left;font-size:0.85em'>class Ev { List&lt;Oda&gt; odalar = new List&lt;Oda&gt;();<br>           public Ev() { odalar.Add(new Oda()); } }</pre>","b":"<b>Composition</b> — parçayı (Oda) bütün (Ev) yaratır ve yok eder.","t":["kod","iliski"]},{"id":"37e933cc8f","f":"C# kodu hangi ilişki?<pre style='text-align:left;font-size:0.85em'>class Rapor { public void Bas(Yazici y) { y.Yaz(); } }</pre>","b":"<b>Dependency</b> (uses-a) — Yazici sadece parametre olarak geçici kullanılıyor.","t":["kod","iliski"]},{"id":"8303cdb9c3","f":"C# kodu hangi ilişki?<pre style='text-align:left;font-size:0.85em'>class C { B myB; public void Do() { myB.Service(); } }   // B, C&#x27;yi bilmiyor</pre>","b":"<b>Unary (directed) association</b>: C → B (ok B'ye).","t":["kod","iliski"]},{"id":"2d8f230052","f":"C# kodu hangi ilişki?<pre style='text-align:left;font-size:0.85em'>interface IUcabilir { void Uc(); }<br>class Kus : IUcabilir { public void Uc() { } }</pre>","b":"<b>Realization</b> — Kus, IUcabilir arayüzünü gerçekleştiriyor (kesikli çizgi + boş üçgen arayüze).","t":["kod","iliski"]},{"id":"8919bb9f8d","f":"Çokluk gösterimleri: <code>1</code>, <code>0..1</code>, <code>*</code>, <code>1..*</code>, <code>n..m</code>?","b":"1: tam bir<br>0..1: sıfır ya da bir<br>0..* / *: sıfır veya daha fazla<br>1..*: en az bir<br>n..m: n ile m arası","t":["notasyon","cikmis"]},{"id":"1b8a960761","f":"Çokluk okuma kuralı?","b":"&quot;<b>Bir</b> A'nın, <b>B tarafındaki sayı kadar</b> B'si vardır.&quot; Hoca: sadece &quot;binary association&quot; deyip bırakma; <b>sayıları cümleyle yorumla</b>.","t":["sinav_taktigi","hoca_sorar"]},{"id":"612039b533","f":"Customer (1) ——— (0..*) Order. Yorumla.","b":"<b>Binary association</b>: bir müşterinin <b>sıfır veya daha fazla</b> siparişi olabilir; her sipariş <b>tek bir</b> müşteriye aittir. İkisi birbirinden haberdar.","t":["cikmis","yorum"]},{"id":"cd705069c5","f":"UML s.35: Order (1) ◇——— (1..*) OrderDetail <i>(line item)</i>. Yorumla.","b":"<b>Aggregation</b>, boş elmas Order tarafında: bir sipariş, sipariş detaylarından oluşan bir topluluktur; <b>bir siparişin bir veya daha fazla</b> detayı vardır (&quot;5 hamburger, 3 salata&quot;). Her detay bir siparişe aittir.","t":["cikmis","yorum","hoca_sorar"]},{"id":"1baa1b9d9c","f":"UML s.35: OrderDetail (0..*) ——> (1) Item. Yorumla.","b":"<b>Unary (directed) association</b>: OrderDetail, Item'ın metotlarını (<code>getPriceForQuantity</code>, <code>getWeight</code>) çağırır; Item'ın haberi yok. Her detay <b>tam bir</b> ürüne karşılık gelir; bir ürün <b>sıfır veya daha fazla</b> detayda geçebilir.","t":["cikmis","yorum","hoca_sorar"]},{"id":"54a907b748","f":"UML s.35: Order (1) ——> (1..*) Payment. Yorumla.","b":"<b>Unary association</b>: bir siparişin <b>bir veya daha fazla</b> ödemesi olabilir (bir kısmı kart, bir kısmı nakit); her ödeme bir siparişe aittir.","t":["cikmis","yorum","hoca_sorar"]},{"id":"d8058382a8","f":"UML s.35: Credit, Cash, Check ——▷ <i>Payment</i>. Yorumla.","b":"<b>Generalization (inheritance)</b>: üçü de Payment'ın özel hâlleri; ortak <code>amount</code>'u miras alır, kendi niteliklerini ekler (Credit: number, type, expDate; Check: name, bankID). <i>Payment</i> italik → <b>abstract class</b>.","t":["cikmis","yorum","hoca_sorar"]},{"id":"d595c6f7ef","f":"Sınıf diyagramı yorumlama sorusunda cevap sırası?","b":"<ol style='text-align:left'><li>Diyagramın ne sistemi olduğunu ve sınıfları tanıt</li><li>Her ilişkinin <b>türünü</b> yaz</li><li>İki sınıf açısından <b>anlamını</b> cümleyle yaz</li><li><b>Çoklukları</b> cümleyle yorumla</li><li>Varsa abstract/interface/stereotipleri belirt</li></ol>","t":["sinav_taktigi","hoca_sorar"]},{"id":"618c0dda60","f":"Library modeli: Book ——— Author (1). Tür ve anlam?","b":"<b>Association</b>: Book ve Author birbirinden haberdar; kitap yazar(lar) tarafından yazılır, yazarın kitapları vardır.","t":["cikmis","yorum"]},{"id":"88ca59dd6c","f":"Library modeli: Book Item ——▷ Book (2). Tür ve anlam?","b":"<b>Inheritance</b>: Book Item <i>is a</i> Book (kitabın fiziksel kopyası); ISBN, title… miras alır, barcode, RFID, dueDate ekler.","t":["cikmis","yorum"]},{"id":"d985254c0c","f":"Library modeli: Library ◇—— Book Item (3). Tür ve anlam?","b":"<b>Aggregation</b>: kütüphane kitap kopyalarından oluşan bir topluluk içerir; kopya kütüphane olmadan da var olabilir (ödünç, transfer). Boş elmas Library tarafında.","t":["cikmis","yorum"]},{"id":"e32e3ff630","f":"Library modeli: Library ◆—— Catalog (4). Tür ve anlam?","b":"<b>Composition</b>: katalog tam olarak bir kütüphanenin parçası, onsuz var olamaz; kütüphane kataloğu oluşturur/yok eder. Dolu elmas Library tarafında.","t":["cikmis","yorum"]},{"id":"2e58639160","f":"Library modeli: Catalog - - ▷ «interface» Search (5). Tür ve anlam?","b":"<b>Realization</b>: Catalog sınıfı Search arayüzündeki işlemleri gerçekleştirir (Manage'i de gerçekleştirir).","t":["cikmis","yorum"]},{"id":"b67c33fefd","f":"Library modeli: Librarian - - «use» > Search (6). Tür ve anlam?","b":"<b>Dependency</b>: kütüphaneci kitap bulmak için Search arayüzünü kullanır; Search değişirse Librarian etkilenebilir.","t":["cikmis","yorum"]},{"id":"57f2df561b","f":"Rent a car: Firma ◆—— Şube (1..*). Tür ve anlam?","b":"<b>Composition</b>: firmanın bir veya daha fazla şubesi var; şubenin yaşam döngüsünü firma kontrol eder, firma kapanırsa şubeler de yok olur.","t":["cikmis","yorum"]},{"id":"74d83ba1b0","f":"Rent a car: Şube ◇—— Araç (0..*). Tür ve anlam?","b":"<b>Aggregation</b>: şube bir araç topluluğu içerir; araç şubeden bağımsız yaşar, başka şubeye transfer edilebilir. Elmas Şube tarafında.","t":["cikmis","yorum"]},{"id":"448c75dd82","f":"Rent a car: Kiralama ——> Araç. Tür ve anlam?","b":"<b>Directed association</b>: kiralama aracın metotlarını çağırır (<code>musaitMi()</code>, <code>durumGuncelle()</code>); araç kiralamadan habersiz. Her kiralama 1 araç, araç zamanla çok kiralama.","t":["cikmis","yorum"]},{"id":"27762c795d","f":"Rent a car: KrediKartiOdeme, NakitOdeme - - ▷ «interface» IOdeme. Tür ve faydası?","b":"<b>Realization</b> (can-do); yeni ödeme türü eklemek mevcut kodu değiştirmez (<b>Open-Closed</b>).","t":["cikmis","yorum"]},{"id":"ee6a169cb5","f":"Rent a car: Kiralama ◆—— Fatura (1–1). Tür ve anlam?","b":"<b>Composition</b>: fatura kiralama tarafından oluşturulur, kiralama olmadan var olamaz.","t":["cikmis","yorum"]},{"id":"9711048064","f":"Sequence diyagramı notasyonu: nesneler, zaman, lifeline, activation?","b":"<ul style='text-align:left'><li>Aktör ve nesneler (<code>ad : Sınıf</code> ya da <code>: Sınıf</code>) en üstte soldan sağa</li><li><b>Zaman yukarıdan aşağı</b> akar</li><li>Nesne altında kesikli <b>lifeline</b></li><li>Nesne çalışırken ince dikdörtgen <b>activation</b></li></ul>","t":["notasyon","cikmis"]},{"id":"38b537589d","f":"Sequence diyagramında çağrı (call) ve dönüş (return) okları nasıl çizilir?","b":"<b>Çağrı:</b> düz çizgili ok, üzerinde <b>alıcı sınıfın metodu</b> (parametreli).<br><b>Dönüş:</b> kesikli çizgili ok, üzerinde dönen değer.","t":["notasyon","cikmis"]},{"id":"511e029dde","f":"Sequence'de oka yazılan çağrı kimin metodu olmalı? (WhatsApp 2025)","b":"<b>Okun ucundaki (alıcı) sınıfın</b> metodu. Ör. <code>: Arac</code>'a giden ok <code>musaitMi(tarih)</code>.","t":["hoca_sorar","sinav_taktigi"]},{"id":"8c8aef4fb7","f":"Sequence'de <b>self call</b>, nesne oluşturma ve yok etme nasıl gösterilir?","b":"Self call: nesnenin kendi lifeline'ına dönen ok.<br>Oluşturma: «create» / <code>new</code> mesajı.<br>Yok etme: lifeline sonunda <b>X</b>.","t":["notasyon"]},{"id":"f2ec0de2a7","f":"UML 2 sequence'de if/else, if ve döngü nasıl gösterilir?","b":"<b>Combined fragment</b>: <code>alt</code> (if/else, [koşul] bölmeleri), <code>opt</code> (if), <code>loop</code>.","t":["notasyon","cikmis"]},{"id":"62f6522cf2","f":"Sequence'de eğik oklar ve kesişen mesajlar neyi gösterir?","b":"Eğik çizgi: mesaj gecikmesi (gerçek zamanlı sistemler). Kesişen mesajlar genellikle sorun → <b>race condition</b>.","t":["notasyon"]},{"id":"f2d3c39c58","f":"2025–26 sequence sorusunda (24 p) puan kazandıran 7 nokta?","b":"<ol style='text-align:left'><li>Aktör + boundary + control + entity doğru sırada</li><li>Her mesaj okun ucundaki sınıfın metodu, parametreli</li><li>Dönüşler kesikli</li><li>Aktivasyon kutuları</li><li>if/else için <code>alt</code> çerçevesi</li><li>Self call (ör. <code>ucretHesapla</code>)</li><li>Akış use case adımlarıyla tutarlı</li></ol>","t":["cikmis","sinav_taktigi"]},{"id":"ffc64538f9","f":"Rent a car &quot;Araç Kirala&quot; sequence akışını özetle.","b":"<ol style='text-align:left'><li>Personel → KiralamaEkrani: <code>kirala(tc, tarih, sinif)</code></li><li>Ekran → KiralamaKontrol: <code>kiralamaBaslat(...)</code></li><li>Kontrol → Arac: <code>musaitMi(tarih)</code> ⇢ arac/null</li><li><code>alt [müsait]</code>: <code>ucretHesapla(gun)</code> (self), «create» <code>Kiralama(...)</code>, <code>odemeAl(ucret)</code> → IOdeme, <code>durumGuncelle(&quot;Kirada&quot;)</code> → Arac, onay ⇢ ekran</li><li><code>[else]</code>: <code>musaitAracYok()</code> ⇢ ekran</li><li>Ekran ⇢ Personel: <code>sonucuGoster()</code></li></ol>","t":["cikmis","senaryo_cozum"]},{"id":"e8704dc191","f":"<b>Collaboration (communication) diagram</b> sequence'den nasıl ayrılır?","b":"Benzer bilgi, ama <b>dikey zaman ekseni yok</b>; nesneler arası <b>bağlantılar</b> (düz çizgi) ve üzerinde yönlü, <b>numaralı</b> mesajlar. Vurgu statik bağlantılarda.","t":["karsilastirma"]},{"id":"63aa04360b","f":"<b>Object diagram</b> nedir?","b":"Class diyagramının örnekleri ve bağlantıları; belirli bir andaki nesnelerin &quot;fotoğrafı&quot; (<code>örnek : Sınıf</code> + nitelik değerleri).","t":["diyagram"]},{"id":"443c1ac1d8","f":"<b>Package diagram</b> nedir? Kesikli ok ne demek?","b":"Karmaşık class diyagramlarını mantıksal paketlere gruplar (üstünde sekmeli dikdörtgen). Kesikli ok <b>bağımlılıktır</b>: diğer paketteki değişiklik bu paketi değiştirebilir.","t":["diyagram"]},{"id":"1b2a8651ca","f":"<b>Activity diagram</b> nedir? Öğeleri?","b":"&quot;Süslü akış diyagramı&quot;: tek sürecin etkinlik akışı.<br><ul style='text-align:left'><li>Yuvarlatılmış kutu: etkinlik</li><li><b>Swim lanes:</b> hangi nesne hangi etkinlikten sorumlu</li><li>Baklava: dallanma</li><li>Kalın çubuk: <b>fork/join</b> (paralel)</li><li>Başlangıç/bitiş daireleri</li></ul>","t":["diyagram"]},{"id":"08029766f6","f":"<b>State transition (statechart)</b> diyagramı nedir? Geçiş etiketi biçimi?","b":"&quot;Süslü DFA&quot;: bir nesnenin olası durumları ve geçişler. Geçiş: <code>Event [Condition] / Action</code>. Durum içinde <code>entry/</code>, <code>do/</code>, <code>exit/</code>.","t":["diyagram"]},{"id":"1f41ff31e2","f":"<b>Component diagram</b> nedir? Arayüz nasıl gösterilir?","b":"Bileşenler, arayüzleri ve bağımlılıkları (fiziksel yapı). Bileşen: sol üstünde iki sekmeli dikdörtgen; arayüz: <b>lolipop</b> (daire + çizgi); bağımlılık: kesikli ok.","t":["diyagram"]},{"id":"6568b7a5dc","f":"<b>Deployment diagram</b> nedir?","b":"Kurulmuş sistemin donanım ve yazılım fiziksel mimarisi: <b>node</b>'lar (makine/cihaz) ve içlerindeki bileşenler; hangi paket hangi sunucuda.","t":["diyagram"]}]}];
